async def get_table_columns(conn, table: str) -> set[str]:
    async with conn.execute(f"PRAGMA table_info({table})") as c:
        return {row[1] for row in await c.fetchall()}


async def ensure_column(
    conn,
    table: str,
    column: str,
    definition: str,
    backfill_sql: str | None = None,
) -> bool:
    """Добавляет колонку, если её нет, и выполняет backfill.

    Возвращает True, если колонка была добавлена.
    """
    columns = await get_table_columns(conn, table)
    added = column not in columns
    if added:
        await conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")
        log.info("Миграция схемы: %s.%s добавлена", table, column)
    if backfill_sql:
        await conn.execute(backfill_sql)
    return added


async def verify_columns(conn, table: str, required: list[str]) -> None:
    columns = await get_table_columns(conn, table)
    missing = sorted(set(required) - columns)
    if missing:
        raise RuntimeError(
            f"В таблице {table} отсутствуют обязательные колонки: {', '.join(missing)}"
        )


intents = discord.Intents.default()
# Нужен для локальных топов, налогов и корректного состава guild.members.
# В Discord Developer Portal включите Privileged Intent -> Server Members.
intents.members = True

class CastleBot(commands.Bot):
    def __init__(self):
        super().__init__(command_prefix="!", intents=intents)
        self.db = None
        self.db_path = None
        self.data_dir = None
        self.backup_dir = None
        self.background_tasks = []
        self._closing = False
        self._guild_access_synced = False

    async def setup_hook(self):
        # 1. Создаём папку data
        self.data_dir = Path(os.getenv("DATA_DIR", "/app/data"))
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.backup_dir = self.data_dir / "backups"
        self.backup_dir.mkdir(parents=True, exist_ok=True)

        # Файловый лог, чтобы ошибки не терялись на хостинге.
        try:
            file_handler = RotatingFileHandler(
                self.data_dir / "bot.log",
                maxBytes=5 * 1024 * 1024,
                backupCount=3,
                encoding="utf-8",
            )
            file_handler.setFormatter(
                logging.Formatter("%(asctime)s [%(levelname)s] %(name)s: %(message)s")
            )
            logging.getLogger().addHandler(file_handler)
        except Exception:
            pass

        # 2. Подключаемся к базе
        DB_PATH = self.data_dir / "castle.db"
        self.db = await aiosqlite.connect(str(DB_PATH))
        self.db_path = str(DB_PATH)
        await self.db.execute("PRAGMA busy_timeout = 10000")
        await self.db.execute("PRAGMA journal_mode = WAL")
        await self.db.execute("PRAGMA foreign_keys = ON")

        # 3. Бэкап перед миграциями и инициализация таблиц
        await self.backup_database("startup")
        await self.init_db()
        await self.tree.sync()

        await self.load_application_emojis()
        await self.restore_giveaway_views()

        # 4. Запускаем фоновые задачи
        self.background_tasks = [
            self._spawn_background("auction_closer", self.auction_closer()),
            self._spawn_background("market_updater", self.market_updater()),
            self._spawn_background("market_order_closer", self.market_order_closer()),
            self._spawn_background("status_expirer", self.status_expirer()),
            self._spawn_background("giveaway_closer", self.giveaway_closer()),
            self._spawn_background("bank_loan_closer", self.bank_loan_closer()),
            self._spawn_background("tax_collector", self.tax_collector()),
            self._spawn_background("autocollector_task", self.autocollector_task()),
            self._spawn_background("notification_task", self.notification_task()),
            self._spawn_background("war_closer", self.war_closer()),
            self._spawn_background("backup_task", self.backup_task()),
            self._spawn_background("retention_task", self.retention_task()),
            self._spawn_background("health_writer", self.health_writer()),
        ]

    def _spawn_background(self, name: str, coro) -> asyncio.Task:
        """Запускает фоновую задачу с именем и учётом ошибок."""

        async def runner():
            try:
                await coro
            except asyncio.CancelledError:
                raise
            except Exception:
                METRICS.record_background_error(name)
                log.exception("BACKGROUND_TASK: %s", name)

        return asyncio.create_task(runner(), name=f"gen_mania:{name}")

    async def build_health_snapshot(self, deep: bool = False) -> dict:
        """Снимок состояния бота для /health и data/health.json."""
        snapshot = METRICS.snapshot()
        snapshot["guilds"] = len(getattr(self, "guilds", []) or [])
        latency = getattr(self, "latency", None)
        snapshot["gateway_latency_ms"] = (
            round(latency * 1000, 1)
            if latency is not None and not math.isnan(latency)
            else None
        )
        snapshot["db_path"] = self.db_path
        db_size = 0
        if self.db_path:
            for suffix in ("", "-wal", "-shm"):
                path = Path(f"{self.db_path}{suffix}")
                if path.exists():
                    db_size += path.stat().st_size
        snapshot["db_size_bytes"] = db_size
        snapshot["tasks"] = [
            {"name": task.get_name(), "done": task.done()}
            for task in getattr(self, "background_tasks", [])
        ]
        snapshot["tasks_alive"] = sum(
            1 for task in snapshot["tasks"] if not task["done"]
        )
        if deep and self.db is not None:
            try:
                async with self.db.execute("PRAGMA quick_check") as c:
                    row = await c.fetchone()
                snapshot["db_quick_check"] = row[0] if row else "unknown"
            except (aiosqlite.Error, OSError) as exc:
                snapshot["db_quick_check"] = f"error: {exc}"
        return snapshot

    async def health_writer(self):
        """Пишет health.json для внешнего мониторинга."""
        await self.wait_until_ready()
        while not self.is_closed():
            try:
                snapshot = await self.build_health_snapshot()
                target = self.data_dir / "health.json"
                temp = target.with_suffix(".json.tmp")
                temp.write_text(
                    json.dumps(snapshot, ensure_ascii=False, indent=2),
                    encoding="utf-8",
                )
                os.replace(temp, target)
            except Exception:
                log.exception("HEALTH: ошибка записи health.json")
            await asyncio.sleep(HEALTH_WRITE_INTERVAL_SECONDS)

    def _rotate_backups(self):
        if not self.backup_dir:
            return
        backups = sorted(
            self.backup_dir.glob("castle_*.db"),
            key=lambda path: path.stat().st_mtime,
            reverse=True,
        )
        for old in backups[max(1, BACKUP_KEEP):]:
            try:
                old.unlink()
            except OSError:
                pass

    async def backup_database(self, reason: str = "manual"):
        """Создаёт консистентный бэкап SQLite через backup API."""
        if not self.db or not self.db_path or not self.backup_dir:
            return None
        if _DB_TX_OWNER is not None:
            log.warning("Бэкап пропущен: активная managed-транзакция")
            return None

        temp_path = None
        try:
            if not Path(self.db_path).exists() or Path(self.db_path).stat().st_size < 1024:
                return None

            async with _DB_WRITE_LOCK:
                if self.db.in_transaction:
                    await self.db.commit()
                await self.db.execute("PRAGMA wal_checkpoint(FULL)")

                stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                safe_reason = re.sub(r"[^a-zA-Z0-9_-]+", "_", reason)[:24] or "manual"
                final_path = self.backup_dir / f"castle_{stamp}_{safe_reason}.db"
                temp_path = self.backup_dir / f".castle_{stamp}_{safe_reason}.tmp"
                if temp_path.exists():
                    temp_path.unlink()

                target = await aiosqlite.connect(str(temp_path))
                try:
                    await self.db.backup(target)
                finally:
                    await target.close()

                check = await aiosqlite.connect(str(temp_path))
                try:
                    async with check.execute("PRAGMA integrity_check") as c:
                        row = await c.fetchone()
                finally:
                    await check.close()
                if not row or row[0] != "ok":
                    raise RuntimeError(f"integrity_check: {row!r}")

                os.replace(temp_path, final_path)
                self._rotate_backups()
                log.info("Бэкап БД создан: %s", final_path.name)
                return final_path
        except Exception:
            log.exception("Не удалось создать бэкап БД")
            if temp_path and temp_path.exists():
                try:
                    temp_path.unlink()
                except OSError:
                    pass
            return None

    async def backup_task(self):
        await self.wait_until_ready()
        while not self.is_closed():
            try:
                await asyncio.sleep(max(1, BACKUP_INTERVAL_HOURS) * 3600)
                await self.backup_database("scheduled")
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception("Ошибка фонового бэкапа")
                await asyncio.sleep(300)

    async def retention_task(self):
        await self.wait_until_ready()
        while not self.is_closed():
            try:
                await asyncio.sleep(86400)
                now = datetime.datetime.now()
                removed = {}
                async with db_transaction():
                    for table, (column, days) in RETENTION_LIMITS.items():
                        cutoff = (now - datetime.timedelta(days=days)).isoformat()
                        cur = await self.db.execute(
                            f"DELETE FROM {table} WHERE {column} < ?", (cutoff,)
                        )
                        removed[table] = cur.rowcount
                if any(removed.values()):
                    log.info("Retention: удалено %s", removed)
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception("Ошибка retention-задачи")
                await asyncio.sleep(3600)

    async def close(self):
        if self._closing:
            return
        self._closing = True

        for task in self.background_tasks:
            task.cancel()
        if self.background_tasks:
            await asyncio.gather(*self.background_tasks, return_exceptions=True)
        self.background_tasks = []

        if self.db:
            await self.backup_database("shutdown")
            try:
                await self.db.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                await self.db.close()
            except Exception:
                log.exception("Ошибка при закрытии БД")
            finally:
                self.db = None

        await super().close()

    async def war_closer(self):
        await self.wait_until_ready()
        while not self.is_closed():
            try:
                await asyncio.sleep(1800)  # раз в 30 минут
                now = datetime.datetime.now()
                async with self.db.execute("""
                    SELECT id, clan1_id, clan2_id, start_time,
                           clan1_hp, clan2_hp, clan1_damage, clan2_damage
                    FROM clan_wars WHERE status = 'active'
                """) as c:
                    wars = await c.fetchall()

                for war_id, c1, c2, start_time, c1_hp, c2_hp, c1_dmg, c2_dmg in wars:
                    async with db_transaction():
                        async with self.db.execute(
                            "SELECT status FROM clan_wars WHERE id = ?",
                            (war_id,),
                        ) as c:
                            fresh = await c.fetchone()
                        if not fresh or fresh[0] != "active":
                            continue
                        # проверяем, что оба клана ещё существуют
                        async with self.db.execute(
                            "SELECT 1 FROM clans WHERE id IN (?, ?)", (c1, c2)
                        ) as c:
                            existing = await c.fetchall()
                        if len(existing) < 2:
                            # один из кланов распущен — закрываем войну без победителя
                            await self.db.execute(
                                "UPDATE clan_wars SET status = 'finished', winner_id = NULL, end_time = ? WHERE id = ?",
                                (now.isoformat(), war_id)
                            )
                            continue

                        start = datetime.datetime.fromisoformat(start_time)
                        if (now - start).total_seconds() < CLAN_WAR_DURATION_HOURS * 3600:
                            continue

                        c1_hp = c1_hp or 0
                        c2_hp = c2_hp or 0
                        c1_dmg = c1_dmg or 0
                        c2_dmg = c2_dmg or 0

                        if c1_hp or c2_hp:
                            winner = (
                                c1 if c1_hp > c2_hp
                                else c2 if c2_hp > c1_hp
                                else c1 if c1_dmg > c2_dmg
                                else c2 if c2_dmg > c1_dmg
                                else None
                            )
                        else:
                            # совместимость со старыми войнами без HP
                            p1 = await get_clan_power(c1)
                            p2 = await get_clan_power(c2)
                            winner = c1 if p1 > p2 else (c2 if p2 > p1 else None)

                        await self.db.execute(
                            "UPDATE clan_wars SET status = 'finished', winner_id = ?, end_time = ? WHERE id = ?",
                            (winner, now.isoformat(), war_id)
                        )
                        if winner:
                            await self.db.execute(
                                "UPDATE clans SET treasury = treasury + ? WHERE id = ?",
                                (CLAN_WAR_REWARD, winner),
                            )
                            await log_clan(winner, "war_win", f"Победа над кланом {c2 if winner == c1 else c1}")
                            await update_clan_quest(winner, "war", 1)
                            await add_clan_xp(winner, 200)
            except Exception as e:
                log.exception("WAR_CLOSER: ошибка фоновой задачи")
                await asyncio.sleep(600)
      

