def replace_emojis_in_text(text: str) -> str:
    if not isinstance(text, str):
        return text

    for old, key in EMOJI_TEXT_KEYS.items():
        new = get_emoji(key)
        if new and new != old:
            text = text.replace(old, str(new))
    return text


def _clip_embed_text(value, limit: int):
    if isinstance(value, str) and len(value) > limit:
        return value[: limit - 1] + "…"
    return value


class BotEmbed(discord.Embed):
    """Embed с автоматической заменой юникод-эмодзи на кастомные."""

    def __init__(self, **kwargs):
        if kwargs.get("title"):
            kwargs["title"] = _clip_embed_text(
                replace_emojis_in_text(kwargs["title"]), 256
            )
        if kwargs.get("description"):
            kwargs["description"] = _clip_embed_text(
                replace_emojis_in_text(kwargs["description"]), 4096
            )
        super().__init__(**kwargs)

    def add_field(self, *, name, value, inline=True):
        return super().add_field(
            name=_clip_embed_text(replace_emojis_in_text(name), 256),
            value=_clip_embed_text(replace_emojis_in_text(value), 1024),
            inline=inline,
        )

    def set_footer(self, *, text=None, icon_url=None):
        if text is not None:
            text = _clip_embed_text(replace_emojis_in_text(text), 2048)
        return super().set_footer(text=text, icon_url=icon_url)

    def set_field_at(self, index, *, name, value, inline=True):
        return super().set_field_at(
            index,
            name=_clip_embed_text(replace_emojis_in_text(name), 256),
            value=_clip_embed_text(replace_emojis_in_text(value), 1024),
            inline=inline,
        )

    def insert_field_at(self, index, *, name, value, inline=True):
        return super().insert_field_at(
            index,
            name=_clip_embed_text(replace_emojis_in_text(name), 256),
            value=_clip_embed_text(replace_emojis_in_text(value), 1024),
            inline=inline,
        )


def clip_embed_text(value, limit: int):
    """Обрезает текст под лимиты Discord, не ломая отправку embed."""
    text = "" if value is None else str(value)
    if len(text) <= limit:
        return text
    return text[: max(0, limit - 1)] + "…"


async def fix_embed_emojis(embed: discord.Embed) -> discord.Embed:
    """Проходит по всем полям эмбеда и меняет эмодзи на кастомные."""
    if embed.title:
        embed.title = clip_embed_text(replace_emojis_in_text(embed.title), 256)
    if embed.description:
        embed.description = clip_embed_text(
            replace_emojis_in_text(embed.description), 4096
        )
    if embed.footer and embed.footer.text:
        embed.set_footer(
            text=clip_embed_text(
                replace_emojis_in_text(embed.footer.text), 2048
            ),
            icon_url=embed.footer.icon_url,
        )
    if embed.author and embed.author.name:
        embed.set_author(
            name=clip_embed_text(
                replace_emojis_in_text(embed.author.name), 256
            ),
            icon_url=embed.author.icon_url,
            url=embed.author.url,
        )
    
    for i, field in enumerate(embed.fields):
        embed.set_field_at(
            i,
            name=clip_embed_text(replace_emojis_in_text(field.name), 256),
            value=clip_embed_text(replace_emojis_in_text(field.value), 1024),
            inline=field.inline
        )
    return embed



async def get_star_emoji(item_id: str, stars: int, default_emoji: str) -> str:
    """Возвращает эмодзи для генератора с учётом звёздности.

    Персональный emoji предмета (custom из guild_settings) имеет приоритет
    над глобальным emoji_by_star.
    """
    async with bot.db.execute(
        "SELECT emoji, emoji_by_star FROM items WHERE id = ?", (item_id,)
    ) as c:
        row = await c.fetchone()

    base_emoji = row[0] if row else None
    emoji_json = row[1] if row else None

    if default_emoji and base_emoji and default_emoji != base_emoji:
        return f"{default_emoji}({stars}⭐)" if stars > 0 else default_emoji

    if emoji_json:
        try:
            emoji_map = json.loads(emoji_json)
            if str(stars) in emoji_map and emoji_map[str(stars)]:
                return emoji_map[str(stars)]
        except Exception:
            pass

    # Fallback: базовый эмодзи + звёзды
    if stars > 0:
        return f"{default_emoji}({stars}⭐)"
    return default_emoji

async def is_command_disabled(guild_id: int, command_key: str) -> bool:
    settings = await get_settings(guild_id)
    return command_key in settings["disabled_commands"]


async def deny_if_disabled(interaction: discord.Interaction, command_key: str) -> bool:
    """Возвращает True, если раздел отключён в настройках сервера."""
    if interaction.guild_id and await is_command_disabled(interaction.guild_id, command_key):
        if not interaction.response.is_done():
            await interaction.response.send_message(
                "❌ Эта функция отключена администратором сервера.",
                ephemeral=True,
            )
        return True
    return False


