async def get_per_second_income(user_id: int) -> tuple[float, float]:
    bonus = await get_status_bonus(user_id)
    multiplier = 1 + bonus

    # клановый бонус
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0
        multiplier *= (1 + clan_bonus)

    # бонус питомца
    pet_coins = await get_pet_bonus(user_id, "income_coins")
    pet_gems = await get_pet_bonus(user_id, "income_gems")
    # бонус титула
    title_coins = await get_title_bonus(user_id, "income_coins")
    title_gems = await get_title_bonus(user_id, "income_gems")

    # бонус престижа, коллекции и сетов
    prestige_bonus = await get_prestige_bonus(user_id)
    collection_bonus = await get_collection_bonus(user_id)
    set_bonus = await get_set_bonus(user_id)

    multiplier_coins = multiplier * (
        1 + pet_coins + title_coins + prestige_bonus + collection_bonus + set_bonus
    )
    multiplier_gems = multiplier * (
        1 + pet_gems + title_gems + prestige_bonus + collection_bonus + set_bonus
    )

    async with bot.db.execute("""
        SELECT inv.stars, i.income_per_hour, i.income_gems_per_hour
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = 'profile'
    """, (user_id,)) as c:
        rows = await c.fetchall()

    per_sec_coins_raw = 0.0
    per_sec_gems_raw = 0.0
    for stars, inc_coins, inc_gems in rows:
        star_mult = 1 + STAR_BONUS.get(stars, 0)
        per_sec_coins_raw += inc_coins * star_mult
        per_sec_gems_raw += inc_gems * star_mult

    return per_sec_coins_raw * multiplier_coins, per_sec_gems_raw * multiplier_gems




async def calculate_passive_income(user_id: int, guild_id: int = None):
    async with bot.db.execute(
        "SELECT last_collected, last_gem_collected FROM players WHERE user_id = ?",
        (user_id,)
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0, 0
    last_coins_str, last_gems_str = row

    # Все бонусы (статус + клан + питомцы) уже учтены в get_per_second_income
    per_sec_coins, per_sec_gems = await get_per_second_income(user_id)

    now = datetime.datetime.now()

    def apply_offline_penalty(seconds: float) -> float:
        if seconds <= 7200:
            return 1.0
        offline_seconds = seconds - 7200
        effective_seconds = 7200 + offline_seconds * 0.7
        return effective_seconds / seconds

    coins = 0
    if per_sec_coins > 0:
        last = datetime.datetime.fromisoformat(last_coins_str)
        seconds = (now - last).total_seconds()
        penalty = apply_offline_penalty(seconds)
        coins = cap_passive_income(
            seconds * per_sec_coins * penalty, seconds, 0
        )

    gems = 0
    if per_sec_gems > 0:
        last = datetime.datetime.fromisoformat(last_gems_str)
        seconds = (now - last).total_seconds()
        penalty = apply_offline_penalty(seconds)
        gems = int(seconds * per_sec_gems * penalty)

    return coins, gems


async def calculate_full_passive_income(user_id: int) -> tuple[int, int]:
    """Полный доход без офлайн-штрафа и без потолков.

    Используется автосборщиком.
    """
    async with bot.db.execute(
        "SELECT last_collected, last_gem_collected FROM players WHERE user_id = ?",
        (user_id,),
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0, 0

    last_coins_str, last_gems_str = row

    per_sec_coins, per_sec_gems = await get_per_second_income(user_id)
    now = datetime.datetime.now()

    coins = 0
    last_coins = _parse_db_time(last_coins_str)
    if per_sec_coins > 0 and last_coins:
        seconds = max(0.0, (now - last_coins).total_seconds())
        coins = int(seconds * per_sec_coins)

    gems = 0
    last_gems = _parse_db_time(last_gems_str)
    if per_sec_gems > 0 and last_gems:
        seconds = max(0.0, (now - last_gems).total_seconds())
        gems = int(seconds * per_sec_gems)

    return coins, gems


async def collect_income(user_id: int, guild_id: int = None):
    async with db_transaction():
        coins_earned, gems_earned = await calculate_passive_income(user_id, guild_id)
        if coins_earned <= 0 and gems_earned <= 0:
            return 0, 0

        now_iso = datetime.datetime.now().isoformat()
        if coins_earned > 0:
            await bot.db.execute(
                "UPDATE players SET coins = coins + ?, "
                "total_coins_earned = total_coins_earned + ?, "
                "lifetime_production = lifetime_production + ?, "
                "last_collected = ? WHERE user_id = ?",
                (coins_earned, coins_earned, coins_earned, now_iso, user_id)
            )
        if gems_earned > 0:
            await bot.db.execute(
                "UPDATE players SET gems = gems + ?, "
                "total_gems_earned = total_gems_earned + ?, "
                "last_gem_collected = ? WHERE user_id = ?",
                (gems_earned, gems_earned, now_iso, user_id)
            )

        # ежедневные задания
        await update_quest_progress(user_id, "collect_income")
        await update_quest_progress(user_id, "collect_income_3")

        # сюжетные квесты
        await update_story_quests(user_id, "coins", coins_earned)
        await update_story_quests(user_id, "collect_income", 1)

        # достижения за накопление монет/гемов
        await check_achievements(user_id)

        return coins_earned, gems_earned

async def get_menu_welcome_notification(user_id: int, guild_id: int = None) -> str | None:
    """Проверяет, сколько прошло времени с последнего сбора, и возвращает текст уведомления."""
    async with bot.db.execute(
        "SELECT last_collected FROM players WHERE user_id = ?", (user_id,)
    ) as c:
        row = await c.fetchone()
    
    if not row or not row[0]:
        return None
        
    last_collected = datetime.datetime.fromisoformat(row[0])
    now = datetime.datetime.now()
    seconds_passed = (now - last_collected).total_seconds()
    
    # Если прошло меньше 30 минут, уведомление не нужно (чтобы не спамить)
    if seconds_passed < 1800:
        return None
        
    # Считаем доход (не собирая его, просто для отображения)
    coins_earned, gems_earned = await calculate_passive_income(user_id, guild_id)
    
    if coins_earned == 0 and gems_earned == 0:
        return None
        
    # Форматируем время
    hours = int(seconds_passed // 3600)
    minutes = int((seconds_passed % 3600) // 60)
    
    if hours > 0:
        time_str = f"{hours} ч {minutes} мин"
    else:
        time_str = f"{minutes} мин"
        
    coin_emoji = str(BOT_BTN_EMOJIS.get("_coin", "🪙"))
    gem_emoji = str(BOT_BTN_EMOJIS.get("_gem", "💎"))
    
    parts = []
    if coins_earned > 0:
        parts.append(f"{coin_emoji} {coins_earned}")
    if gems_earned > 0:
        parts.append(f"{gem_emoji} {gems_earned}")
        
    income_str = " и ".join(parts)
    
    return (
        f"👋 С возвращением! Пока тебя не было ({time_str}), твои генераторы заработали:\n\n"
        f"**{income_str}**\n\n"
        f"*(Доход уже добавлен в кошелёк, он отображён в меню ниже).*"
    )


async def place_items(user_id: int, item_id: str, quantity: int, commit: bool = True, stars: int = 0) -> tuple[int, int, int]:
    async with db_transaction():
        return await _place_items_unlocked(
            user_id, item_id, quantity, commit=commit, stars=stars
        )


async def _place_items_unlocked(user_id: int, item_id: str, quantity: int, commit: bool = True, stars: int = 0) -> tuple[int, int, int]:
    grid_size = await get_grid_size(user_id)
    storage_size = await get_storage_size(user_id)
    temp_size = TEMP_STORAGE_SIZE

    async with bot.db.execute(
        "SELECT slot FROM inventory WHERE user_id = ? AND location = 'profile'", (user_id,)
    ) as c:
        used_profile = {r[0] for r in await c.fetchall()}
    free_profile = [s for s in range(grid_size) if s not in used_profile]

    async with bot.db.execute(
        "SELECT slot FROM inventory WHERE user_id = ? AND location = 'storage'", (user_id,)
    ) as c:
        used_storage = {r[0] for r in await c.fetchall()}
    free_storage = [s for s in range(storage_size) if s not in used_storage]

    async with bot.db.execute(
        "SELECT slot FROM inventory WHERE user_id = ? AND location = 'temp'", (user_id,)
    ) as c:
        used_temp = {r[0] for r in await c.fetchall()}
    free_temp = [s for s in range(temp_size) if s not in used_temp]

    total_free = len(free_profile) + len(free_storage) + len(free_temp)
    if total_free < quantity:
        raise ValueError(
            f"Не хватает места: свободно {total_free} "
            f"(энергостанция + хранилище + временное), нужно {quantity}."
        )

    to_profile = min(quantity, len(free_profile))
    remaining = quantity - to_profile
    to_storage = min(remaining, len(free_storage))
    to_temp = remaining - to_storage

    for i in range(to_profile):
        await bot.db.execute(
            "INSERT INTO inventory (user_id, slot, item_id, location, stars) VALUES (?, ?, ?, 'profile', ?)",
            (user_id, free_profile[i], item_id, stars)
        )
    for i in range(to_storage):
        await bot.db.execute(
            "INSERT INTO inventory (user_id, slot, item_id, location, stars) VALUES (?, ?, ?, 'storage', ?)",
            (user_id, free_storage[i], item_id, stars)
        )
    for i in range(to_temp):
        await bot.db.execute(
            "INSERT INTO inventory (user_id, slot, item_id, location, stars) VALUES (?, ?, ?, 'temp', ?)",
            (user_id, free_temp[i], item_id, stars)
        )
    await bot.db.execute(
        "INSERT OR IGNORE INTO player_collection (user_id, item_id) VALUES (?, ?)",
        (user_id, item_id),
    )
    try:
        await bot.db.execute(
            "INSERT OR IGNORE INTO player_star_collection "
            "(user_id, item_id, stars) VALUES (?, ?, ?)",
            (user_id, item_id, stars),
        )
    except aiosqlite.OperationalError:
        # Старые/упрощённые схемы могут не иметь таблицы звёздной коллекции.
        pass
    if commit:
        await commit_if_needed()
    return to_profile, to_storage, to_temp


async def grant_item_or_compensation(user_id: int, item_id: str, quantity: int = 1, stars: int = 0) -> tuple[str, int]:
    """Выдаёт предмет. Если места нет — отправляет его в почту.

    Второй элемент возврата оставлен для совместимости и всегда 0:
    полная денежная компенсация больше не начисляется.
    """
    async with bot.db.execute("SELECT name FROM items WHERE id = ?", (item_id,)) as c:
        row = await c.fetchone()
    name = row[0] if row else item_id

    try:
        await place_items(user_id, item_id, quantity, commit=False, stars=stars)
        await commit_if_needed()
        return name, 0
    except ValueError:
        await bot.db.execute(
            "INSERT INTO mailbox (user_id, item_id, quantity, stars, reason) "
            "VALUES (?, ?, ?, ?, 'no_space')",
            (user_id, item_id, quantity, stars),
        )
        await commit_if_needed()
        return f"{name} (нет места — отправлен в почту)", 0


async def _reslot_inventory(user_id: int, location: str, rows: list):
    """Безопасно переставляет предметы по слотам через временные отрицательные слоты."""
    if not rows:
        return

    for idx, row in enumerate(rows):
        old_slot = row[0]
        await bot.db.execute(
            "UPDATE inventory SET slot = ? WHERE user_id = ? AND location = ? AND slot = ?",
            (-(idx + 1), user_id, location, old_slot),
        )

    for new_slot, row in enumerate(rows):
        await bot.db.execute(
            "UPDATE inventory SET slot = ? WHERE user_id = ? AND location = ? AND slot = ?",
            (new_slot, user_id, location, -(new_slot + 1)),
        )
    await commit_if_needed()


async def sort_inventory(user_id: int, location: str):
    async with bot.db.execute("""
        SELECT inv.slot, inv.item_id, inv.stars, i.price
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = ?
        ORDER BY i.price DESC, inv.stars DESC
    """, (user_id, location)) as c:
        rows = await c.fetchall()

    await _reslot_inventory(user_id, location, rows)

async def sort_inventory_by(user_id: int, location: str, sort_type: str):
    """Сортирует инвентарь по выбранному критерию."""
    # Получаем все предметы
    async with bot.db.execute("""
        SELECT inv.slot, inv.item_id, inv.stars, i.price, i.income_per_hour, i.rarity
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = ?
    """, (user_id, location)) as c:
        rows = await c.fetchall()

    if not rows:
        return

    rarity_order = {"common": 1, "uncommon": 2, "rare": 3, "epic": 4, "legendary": 5, "mythic": 6}

    if sort_type == "price_desc":
        rows.sort(key=lambda r: r[3], reverse=True)
    elif sort_type == "price_asc":
        rows.sort(key=lambda r: r[3])
    elif sort_type == "stars_desc":
        rows.sort(key=lambda r: (r[2], r[3]), reverse=True)
    elif sort_type == "stars_asc":
        rows.sort(key=lambda r: (r[2], r[3]))
    elif sort_type == "income_desc":
        rows.sort(key=lambda r: r[4], reverse=True)
    elif sort_type == "rarity_desc":
        rows.sort(key=lambda r: (rarity_order.get(r[5], 0), r[3]), reverse=True)
    else:
        # По умолчанию: цена (убывание), затем звёзды
        rows.sort(key=lambda r: (r[3], r[2]), reverse=True)

    await _reslot_inventory(user_id, location, rows)

async def log_admin_action(
    admin_id: int,
    target_id: int,
    action: str,
    details: str = "",
    guild_id: int | None = None,
):
    if guild_id is None:
        guild_id = _CURRENT_GUILD_ID.get()
    await bot.db.execute(
        "INSERT INTO admin_log (admin_id, target_id, guild_id, action, details) "
        "VALUES (?, ?, ?, ?, ?)",
        (admin_id, target_id, guild_id, action, details),
    )
    await commit_if_needed()

# ============================================================
#  📦 КОНТЕНТ-РЕДАКТОР: ВАЛИДАЦИЯ И РЕВИЗИИ
# ============================================================

CONTENT_ID_RE = re.compile(r"^[a-z][a-z0-9_]{1,31}$")
CONTENT_MAX_NAME = 100
CONTENT_MAX_DESCRIPTION = 500
CONTENT_MAX_PRICE = 10**12
CONTENT_MAX_INCOME = 10**9
CONTENT_PAGE_SIZE = 24
CONTENT_RARITIES = tuple(RARITY_COLORS.keys())


def normalize_content_id(value) -> str | None:
    value = (str(value) if value is not None else "").strip()
    return value if CONTENT_ID_RE.fullmatch(value) else None


def normalize_content_name(value, max_length: int = CONTENT_MAX_NAME) -> str | None:
    value = (str(value) if value is not None else "").strip()
    if not value or len(value) > max_length:
        return None
    return value


def parse_content_int(value, maximum: int = CONTENT_MAX_PRICE) -> int | None:
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        return None
    if number < 0 or number > maximum:
        return None
    return number


def parse_content_float(value, maximum: float = CONTENT_MAX_INCOME) -> float | None:
    try:
        number = float(str(value).strip().replace(",", "."))
    except (TypeError, ValueError):
        return None
    if not (0 <= number <= maximum):
        return None
    return number


def format_content_number(value) -> str:
    if isinstance(value, float):
        text = f"{value:.8f}".rstrip("0").rstrip(".")
        return text or "0"
    return str(value if value is not None else 0)


def is_non_negative_number(value) -> bool:
    try:
        return float(value) >= 0
    except (TypeError, ValueError):
        return False


async def get_content_status() -> dict:
    """Возвращает версию контента и данные последней ручной правки."""
    status = {
        "content_version": 0,
        "manual_revision": 0,
        "last_editor_id": None,
        "last_edit_at": None,
    }
    async with bot.db.execute(
        "SELECT key, value FROM content_meta WHERE key IN "
        "('content_version', 'manual_revision', "
        "'last_content_editor_id', 'last_content_edit_at')"
    ) as c:
        rows = await c.fetchall()
    for key, value in rows:
        if key in ("content_version", "manual_revision"):
            try:
                status[key] = int(value)
            except (TypeError, ValueError):
                status[key] = 0
        elif key == "last_content_editor_id":
            try:
                status["last_editor_id"] = int(value)
            except (TypeError, ValueError):
                status["last_editor_id"] = None
        else:
            status["last_edit_at"] = value
    return status


async def deny_content_edit(interaction: discord.Interaction) -> bool:
    """True, если правку контента нужно отклонить."""
    if await is_global_owner(interaction):
        return False
    await interaction.response.send_message(
        "❌ Контент может менять только владелец бота.",
        ephemeral=True,
    )
    return True


async def record_content_edit(
    editor_id: int,
    entity: str,
    entity_id: str,
    action: str = "edit",
    details: str = "",
):
    """Фиксирует ручную правку контента и увеличивает ревизию."""
    await bot.db.execute(
        "INSERT INTO content_meta (key, value) VALUES ('manual_revision', '1') "
        "ON CONFLICT(key) DO UPDATE SET value = CAST(value AS INTEGER) + 1"
    )
    await bot.db.execute(
        "INSERT INTO content_meta (key, value) VALUES ('last_content_editor_id', ?) "
        "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
        (str(editor_id),),
    )
    await bot.db.execute(
        "INSERT INTO content_meta (key, value) VALUES "
        "('last_content_edit_at', CURRENT_TIMESTAMP) "
        "ON CONFLICT(key) DO UPDATE SET value = CURRENT_TIMESTAMP"
    )
    await log_admin_action(
        editor_id,
        0,
        f"content_{entity}_{action}",
        details or str(entity_id),
    )


async def validate_content_data() -> list[str]:
    """Проверяет предметы и достижения на явно некорректные значения."""
    issues: list[str] = []
    async with bot.db.execute(
        "SELECT id, name, price, income_per_hour, income_gems_per_hour, "
        "rarity, buyable, emoji FROM items ORDER BY id"
    ) as c:
        items = await c.fetchall()
    for item_id, name, price, income, gem_income, rarity, buyable, emoji in items:
        if not normalize_content_id(item_id):
            issues.append(f"предмет `{item_id}`: неверный ID")
        if not normalize_content_name(name):
            issues.append(f"предмет `{item_id}`: пустое или длинное название")
        if price is None or not is_non_negative_number(price):
            issues.append(f"предмет `{item_id}`: цена < 0")
        if not is_non_negative_number(income):
            issues.append(f"предмет `{item_id}`: доход монет < 0")
        if not is_non_negative_number(gem_income):
            issues.append(f"предмет `{item_id}`: доход гемов < 0")
        if rarity not in RARITY_COLORS:
            issues.append(f"предмет `{item_id}`: неизвестная редкость `{rarity}`")
        if buyable not in (0, 1, None):
            issues.append(f"предмет `{item_id}`: buyable должен быть 0/1")
        if not emoji or not is_valid_emoji(str(emoji)):
            issues.append(f"предмет `{item_id}`: неверный эмодзи")

    async with bot.db.execute(
        "SELECT id, name, description, reward_gems, emoji "
        "FROM achievements ORDER BY id"
    ) as c:
        achievements = await c.fetchall()
    for ach_id, name, description, reward, emoji in achievements:
        if not normalize_content_id(ach_id):
            issues.append(f"достижение `{ach_id}`: неверный ID")
        if not normalize_content_name(name):
            issues.append(f"достижение `{ach_id}`: пустое или длинное название")
        if not normalize_content_name(description, CONTENT_MAX_DESCRIPTION):
            issues.append(f"достижение `{ach_id}`: пустое или длинное описание")
        if reward is None or not is_non_negative_number(reward):
            issues.append(f"достижение `{ach_id}`: награда < 0")
        if not emoji or not is_valid_emoji(str(emoji)):
            issues.append(f"достижение `{ach_id}`: неверный эмодзи")

    return issues[:20]


async def update_item_content(
    editor_id: int,
    item_id: str,
    name_value,
    price_value,
    income_value,
    gem_income_value,
    rarity_value,
) -> tuple[bool, str]:
    item_id = normalize_content_id(item_id)
    if not item_id:
        return False, "❌ ID: латиница в нижнем регистре, цифры и `_` (2–32 символа)."
    name = normalize_content_name(name_value)
    if not name:
        return False, "❌ Название: от 1 до 100 символов."
    price = parse_content_int(price_value)
    if price is None:
        return False, "❌ Цена: целое число от 0."
    income = parse_content_float(income_value)
    if income is None:
        return False, "❌ Доход монет: число от 0."
    gem_income = parse_content_float(gem_income_value)
    if gem_income is None:
        return False, "❌ Доход гемов: число от 0."
    rarity = (str(rarity_value) if rarity_value is not None else "").strip().lower()
    if rarity not in RARITY_COLORS:
        return False, f"❌ Редкость: {', '.join(RARITY_COLORS.keys())}."

    async with bot.db.execute(
        "SELECT 1 FROM items WHERE id = ?", (item_id,)
    ) as c:
        if not await c.fetchone():
            return False, f"❌ Предмет `{item_id}` не найден."

    async with db_transaction():
        await bot.db.execute(
            "UPDATE items SET name = ?, price = ?, income_per_hour = ?, "
            "income_gems_per_hour = ?, rarity = ? WHERE id = ?",
            (name, price, income, gem_income, rarity, item_id),
        )
        await record_content_edit(
            editor_id,
            "item",
            item_id,
            "edit",
            f"name={name}, price={price}, rarity={rarity}",
        )
    return True, f"✅ Предмет `{item_id}` обновлён."


async def update_item_appearance(
    editor_id: int,
    item_id: str,
    emoji_value,
    buyable_value,
) -> tuple[bool, str]:
    item_id = normalize_content_id(item_id)
    if not item_id:
        return False, "❌ Неверный ID предмета."
    emoji = (str(emoji_value) if emoji_value is not None else "").strip()
    if not is_valid_emoji(emoji):
        return False, "❌ Эмодзи: юникод-символ или `<:name:id>`."
    buyable = parse_content_int(buyable_value, maximum=1)
    if buyable is None:
        return False, "❌ Покупаемость: 1 или 0."

    async with bot.db.execute(
        "SELECT 1 FROM items WHERE id = ?", (item_id,)
    ) as c:
        if not await c.fetchone():
            return False, f"❌ Предмет `{item_id}` не найден."

    async with db_transaction():
        await bot.db.execute(
            "UPDATE items SET emoji = ?, buyable = ? WHERE id = ?",
            (emoji, buyable, item_id),
        )
        await record_content_edit(
            editor_id,
            "item",
            item_id,
            "appearance",
            f"emoji={emoji}, buyable={buyable}",
        )
    return True, f"✅ Вид предмета `{item_id}` обновлён."


async def set_item_price(
    editor_id: int, item_id: str, price_value
) -> tuple[bool, str]:
    item_id = normalize_content_id(item_id)
    if not item_id:
        return False, "❌ Неверный ID предмета."
    price = parse_content_int(price_value)
    if price is None:
        return False, "❌ Цена: целое число от 0."
    async with bot.db.execute(
        "SELECT name FROM items WHERE id = ?", (item_id,)
    ) as c:
        row = await c.fetchone()
    if not row:
        return False, f"❌ `{item_id}` не найден."
    async with db_transaction():
        await bot.db.execute(
            "UPDATE items SET price = ? WHERE id = ?", (price, item_id)
        )
        await record_content_edit(
            editor_id, "item", item_id, "price", f"price={price}"
        )
    return True, f"✅ Цена **{row[0]}** = 🪙 {price}."


async def set_item_income(
    editor_id: int, item_id: str, income_value, gem_income_value
) -> tuple[bool, str]:
    item_id = normalize_content_id(item_id)
    if not item_id:
        return False, "❌ Неверный ID предмета."
    async with bot.db.execute(
        "SELECT name, income_per_hour, income_gems_per_hour "
        "FROM items WHERE id = ?",
        (item_id,),
    ) as c:
        row = await c.fetchone()
    if not row:
        return False, f"❌ `{item_id}` не найден."

    income_text = (str(income_value) if income_value is not None else "").strip()
    gem_text = (
        str(gem_income_value) if gem_income_value is not None else ""
    ).strip()
    income = parse_content_float(income_text) if income_text else (row[1] or 0)
    gem_income = parse_content_float(gem_text) if gem_text else (row[2] or 0)
    if income is None:
        return False, "❌ Неверный доход монет."
    if gem_income is None:
        return False, "❌ Неверный доход гемов."

    async with db_transaction():
        await bot.db.execute(
            "UPDATE items SET income_per_hour = ?, income_gems_per_hour = ? "
            "WHERE id = ?",
            (income, gem_income, item_id),
        )
        await record_content_edit(
            editor_id,
            "item",
            item_id,
            "income",
            f"coins={format_content_number(income)}, "
            f"gems={format_content_number(gem_income)}",
        )
    return True, (
        f"✅ Доход **{row[0]}**: 🪙 {format_content_number(income)}/час, "
        f"💎 {format_content_number(gem_income)}/час."
    )


