async def get_notifications(user_id: int) -> dict:
    """Возвращает {notif_type: (enabled, last_sent)} для всех типов. Если записи нет — enabled=True по умолчанию."""
    async with bot.db.execute(
        "SELECT notif_type, enabled, last_sent FROM user_notifications WHERE user_id = ?", (user_id,)
    ) as c:
        rows = await c.fetchall()

    result = {t: (1, None) for t in NOTIFICATION_TYPES}  # по умолчанию включено
    for ntype, enabled, last_sent in rows:
        result[ntype] = (enabled, last_sent)
    return result

async def get_top_players(
    top_type: str, limit: int = 10, guild_id: int | None = None
) -> list:
    """Возвращает список (user_id, value) для указанного топа.

    guild_id=None — глобальный топ; иначе только участники этого сервера.
    """
    member_ids = None
    if guild_id:
        guild = bot.get_guild(guild_id) if hasattr(bot, "get_guild") else None
        if guild is None:
            return []
        member_ids = [member.id for member in guild.members]

    def user_filter(column: str = "user_id") -> tuple[str, list]:
        if member_ids is None:
            return "", []
        if not member_ids:
            return " AND 0", []
        placeholders = ",".join("?" for _ in member_ids)
        return f" AND {column} IN ({placeholders})", list(member_ids)

    if top_type == "coins":
        where, params = user_filter()
        async with bot.db.execute(
            f"SELECT user_id, coins FROM players WHERE 1=1 {where} "
            f"AND COALESCE(top_excluded, 0) = 0 "
            f"ORDER BY coins DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "gems":
        where, params = user_filter()
        async with bot.db.execute(
            f"SELECT user_id, gems FROM players WHERE 1=1 {where} "
            f"AND COALESCE(top_excluded, 0) = 0 "
            f"ORDER BY gems DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "crafts":
        where, params = user_filter()
        async with bot.db.execute(
            f"SELECT user_id, total_crafts FROM players WHERE 1=1 {where} "
            f"AND COALESCE(top_excluded, 0) = 0 "
            f"ORDER BY total_crafts DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "pets":
        where, params = user_filter("up.user_id")
        async with bot.db.execute(
            f"SELECT up.user_id, COUNT(*) AS cnt FROM user_pets_v2 up "
            f"JOIN players p ON p.user_id = up.user_id "
            f"WHERE 1=1 {where} AND COALESCE(p.top_excluded, 0) = 0 "
            f"GROUP BY up.user_id ORDER BY cnt DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "power":
        where, params = user_filter("inv.user_id")
        candidate_limit = max(limit * 10, 100)
        async with bot.db.execute(
            f"SELECT inv.user_id, SUM(i.price * (1 + inv.stars * 0.5)) AS power "
            f"FROM inventory inv JOIN items i ON inv.item_id = i.id "
            f"JOIN players p ON p.user_id = inv.user_id "
            f"WHERE inv.location = 'profile' AND COALESCE(p.top_excluded, 0) = 0 "
            f"{where} GROUP BY inv.user_id ORDER BY power DESC LIMIT ?",
            (*params, candidate_limit),
        ) as c:
            raw_rows = await c.fetchall()
        powers = await get_combat_power_many(
            [user_id for user_id, _raw_power in raw_rows]
        )
        scored = [
            (user_id, powers.get(user_id, 0)) for user_id, _raw in raw_rows
        ]
        scored.sort(key=lambda row: row[1], reverse=True)
        return scored[:limit]

    elif top_type == "clans":
        clan_where = ""
        clan_params: list = []
        if member_ids is not None:
            if not member_ids:
                return []
            placeholders = ",".join("?" for _ in member_ids)
            clan_where = (
                " WHERE EXISTS (SELECT 1 FROM clan_members cm2 "
                f"WHERE cm2.clan_id = c.id AND cm2.user_id IN ({placeholders}))"
            )
            clan_params = list(member_ids)
        clan_where = (clan_where or " WHERE 1=1") + (
            " AND (c.leader_id IS NULL OR c.leader_id NOT IN "
            "(SELECT user_id FROM players WHERE COALESCE(top_excluded, 0) = 1))"
        )
        async with bot.db.execute(
            f"""
            SELECT c.id, c.name,
                COALESCE((
                    SELECT SUM(i.price * (1 + ci.stars * 0.5))
                    FROM clan_inventory ci
                    JOIN items i ON ci.item_id = i.id
                    WHERE ci.clan_id = c.id
                ), 0)
                + COALESCE((
                    SELECT SUM(mp.power) FROM (
                        SELECT SUM(i2.price * (1 + inv.stars * 0.5)) AS power
                        FROM inventory inv
                        JOIN items i2 ON inv.item_id = i2.id
                        JOIN clan_members cm ON cm.user_id = inv.user_id
                        WHERE cm.clan_id = c.id AND inv.location = 'profile'
                        GROUP BY inv.user_id
                    ) mp
                ), 0) AS power
            FROM clans c
            {clan_where}
            ORDER BY power DESC
            LIMIT ?
            """,
            (*clan_params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "prestige":
        where, params = user_filter()
        async with bot.db.execute(
            f"SELECT user_id, prestige_points FROM players WHERE 1=1 {where} "
            f"AND COALESCE(top_excluded, 0) = 0 "
            f"ORDER BY prestige_points DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "collection":
        where, params = user_filter("pc.user_id")
        async with bot.db.execute(
            f"SELECT pc.user_id, COUNT(*) AS cnt FROM player_collection pc "
            f"JOIN players p ON p.user_id = pc.user_id "
            f"WHERE 1=1 {where} AND COALESCE(p.top_excluded, 0) = 0 "
            f"GROUP BY pc.user_id ORDER BY cnt DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    elif top_type == "duels":
        where, params = user_filter("dh.winner_id")
        async with bot.db.execute(
            f"SELECT dh.winner_id AS user_id, COUNT(*) AS wins "
            f"FROM duel_history dh "
            f"JOIN players p ON p.user_id = dh.winner_id "
            f"WHERE 1=1 {where} AND COALESCE(p.top_excluded, 0) = 0 "
            f"GROUP BY dh.winner_id ORDER BY wins DESC LIMIT ?",
            (*params, limit),
        ) as c:
            return await c.fetchall()

    return []

_top_cache = {}  # {top_type: (timestamp, rows)}
TOP_CACHE_TTL = 300  # 5 минут


async def get_top_players_cached(
    top_type: str, limit: int = 10, guild_id: int | None = None
) -> list:
    """Кэширует результаты топов на 5 минут."""
    now = datetime.datetime.now().timestamp()
    cache_key = f"{top_type}:{limit}:{guild_id or 'global'}"
    if cache_key in _top_cache:
        ts, rows = _top_cache[cache_key]
        if now - ts < TOP_CACHE_TTL:
            return rows

    rows = await get_top_players(top_type, limit, guild_id)
    _top_cache[cache_key] = (now, rows)
    return rows


async def enforce_top_exclusion(
    interaction: discord.Interaction,
    target_id: int,
    reason: str,
) -> bool:
    """Исключает админа/владельца из топов после выдачи ресурса себе."""
    if target_id != interaction.user.id:
        return False
    cur = await bot.db.execute(
        "UPDATE players SET top_excluded = 1 "
        "WHERE user_id = ? AND COALESCE(top_excluded, 0) = 0",
        (target_id,),
    )
    await commit_if_needed()
    _top_cache.clear()
    if cur.rowcount == 0:
        return False
    await log_admin_action(
        target_id,
        target_id,
        "top_exclusion",
        reason,
        guild_id=getattr(interaction, "guild_id", None),
    )
    try:
        await interaction.followup.send(TOP_EXCLUSION_NOTICE, ephemeral=True)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        pass
    return True

async def get_advent_state(user_id: int) -> tuple:
    """Возвращает (last_opened_day, last_opened_date, event_key)."""
    async with bot.db.execute(
        "SELECT last_opened_day, last_opened_date, event_key "
        "FROM advent_state WHERE user_id = ?",
        (user_id,),
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0, None, None
    return row[0] or 0, row[1], row[2]


async def get_advent_opened(user_id: int) -> set:
    """Возвращает set открытых дней текущего праздничного события."""
    event, _day = get_active_advent_event()
    if not event:
        return set()
    _last_day, _last_date, event_key = await get_advent_state(user_id)
    if event_key != event["key"]:
        return set()
    async with bot.db.execute(
        "SELECT day FROM advent_progress WHERE user_id = ?", (user_id,)
    ) as c:
        return {r[0] for r in await c.fetchall()}


async def can_open_advent_today(user_id: int) -> tuple[bool, str]:
    """Проверяет, можно ли открыть окошко сегодня."""
    event, _day = get_active_advent_event()
    if not event:
        return False, "Сейчас нет активного праздничного календаря."
    last_day, last_date, event_key = await get_advent_state(user_id)
    if event_key == event["key"] and last_day >= event["days"]:
        return False, f"{event['emoji']} Все окошки события уже открыты!"
    last = _parse_market_datetime(last_date)
    if last and (datetime.date.today() - last.date()).days < 1:
        return False, "⏳ Ты уже открывал окошко сегодня. Возвращайся завтра!"
    return True, ""


async def open_advent_day(user_id: int, day: int) -> tuple[bool, str, dict]:
    """Открывает окошко активного праздничного события."""
    event, _current_day = get_active_advent_event()
    if not event:
        return False, "🎄 Сейчас нет активного праздничного календаря.", {}
    if day < 1 or day > event["days"]:
        return False, f"❌ В этом событии доступны дни 1–{event['days']}.", {}

    try:
        async with db_transaction():
            last_day, last_date, event_key = await get_advent_state(user_id)
            if event_key != event["key"]:
                await bot.db.execute(
                    "DELETE FROM advent_progress WHERE user_id = ?", (user_id,)
                )
                last_day = 0
                last_date = None

            if last_day >= event["days"]:
                raise ValueError(
                    f"❌ {event['emoji']} Все окошки события уже открыты!"
                )
            last_date_value = _parse_market_datetime(last_date)
            if last_date_value:
                if (
                    datetime.date.today() - last_date_value.date()
                ).days < 1:
                    raise ValueError(
                        "⏳ Ты уже открывал окошко сегодня. "
                        "Возвращайся завтра!"
                    )
            async with bot.db.execute(
                "SELECT 1 FROM advent_progress "
                "WHERE user_id = ? AND day = ?",
                (user_id, day),
            ) as c:
                if await c.fetchone():
                    raise ValueError("❌ Это окошко уже открыто.")
            if day != last_day + 1:
                raise ValueError(
                    f"❌ Сейчас можно открыть только окошко **{last_day + 1}**."
                )

            coins, gems, item_id = ADVENT_REWARDS[day]
            await bot.db.execute(
                "UPDATE players SET coins = coins + ?, gems = gems + ?, "
                "total_coins_earned = total_coins_earned + ?, "
                "lifetime_production = lifetime_production + ?, "
                "total_gems_earned = total_gems_earned + ? "
                "WHERE user_id = ?",
                (coins, gems, coins, coins, gems, user_id),
            )

            item_name = None
            if item_id:
                item_name, _ = await grant_item_or_compensation(
                    user_id, item_id, 1
                )

            now_iso = datetime.datetime.now().isoformat()
            today_str = datetime.date.today().isoformat()
            await bot.db.execute(
                "INSERT INTO advent_progress (user_id, day) VALUES (?, ?)",
                (user_id, day),
            )
            await bot.db.execute("""
                INSERT INTO advent_state
                    (user_id, last_opened_day, last_opened_date, event_key)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(user_id) DO UPDATE SET
                    last_opened_day = ?,
                    last_opened_date = ?,
                    event_key = ?
            """, (
                user_id, day, today_str, event["key"],
                day, today_str, event["key"],
            ))
    except ValueError as exc:
        return False, str(exc), {}

    await check_achievements(user_id)

    return True, f"🎁 Окошко **{day}** открыто!", {
        "day": day, "coins": coins, "gems": gems, "item": item_name
    }


async def build_top_embed(
    interaction: discord.Interaction,
    top_type: str,
    limit: int = 10,
    scope: str = "global",
) -> discord.Embed:
    """Строит embed для указанного топа (global/local)."""
    if top_type not in TOP_TYPES:
        top_type = "coins"
    title, _ = TOP_TYPES[top_type]
    top_emoji = get_emoji(TOP_TYPE_EMOJIS.get(top_type, "_stats"))
    guild_id = interaction.guild_id if scope == "local" else None

    rows = await get_top_players_cached(top_type, limit, guild_id)

    embed = BotEmbed(
        title=f"{top_emoji} Топ — {title}",
        description=(
            f"{'Локальный' if scope == 'local' else 'Глобальный'} топ-{limit} "
            f"{'кланов' if top_type == 'clans' else 'игроков'}"
        ),
        color=0xf1c40f,
    )

    if not rows:
        embed.description = "Пока нет данных."
        return embed

    user_cache: dict[int, object] = {}
    if top_type != "clans":
        missing = []
        for uid, _value in rows:
            user = bot.get_user(uid)
            if user is not None:
                user_cache[uid] = user
            else:
                missing.append(uid)
        if missing:
            semaphore = asyncio.Semaphore(5)

            async def fetch_one(uid: int):
                async with semaphore:
                    try:
                        return uid, await bot.fetch_user(uid)
                    except (discord.NotFound, discord.HTTPException):
                        return uid, None

            fetched = await asyncio.gather(
                *(fetch_one(uid) for uid in missing)
            )
            for uid, user in fetched:
                if user is not None:
                    user_cache[uid] = user

    lines = []
    for i, row in enumerate(rows, start=1):
        if top_type == "clans":
            clan_id, name, power = row
            lines.append(f"**{i}.** 🏰 {name} — ⚔️ {power}")
        else:
            uid, value = row
            user = user_cache.get(uid)
            display = f"**{user.name}**" if user else f"`{uid}`"
            lines.append(f"**{i}.** {display} — {value}")

    # Разбиваем на поля по 10 строк, чтобы не превысить лимит 1024 символа в поле
    chunk_size = 10
    for i in range(0, len(lines), chunk_size):
        chunk = lines[i:i+chunk_size]
        start = i + 1
        end = i + len(chunk)
        embed.add_field(
            name=f"Места {start}–{end}",
            value="\n".join(chunk),
            inline=False
        )
    embed = await fix_embed_emojis(embed)
    return embed

async def build_advent_embed(interaction: discord.Interaction, page: int = 0) -> discord.Embed:
    event, _current_day = get_active_advent_event()
    if not event:
        e = BotEmbed(
            title="🎄 Праздничный календарь",
            description=(
                "Сейчас нет активного события. Календарь открывается на праздники: "
                "зимние праздники, Хэллоуин, майские, 23 февраля и 8 Марта."
            ),
            color=0xe74c3c,
        )
        return await fix_embed_emojis(e)
    event_days = event["days"]
    user_id = interaction.user.id
    opened = await get_advent_opened(user_id)
    last_day, _last_date, event_key = await get_advent_state(user_id)
    if event_key != event["key"]:
        last_day = 0

    can_today, reason = await can_open_advent_today(user_id)
    next_day = last_day + 1
    total_pages = max(1, (event_days + ADVENT_PAGE_SIZE - 1) // ADVENT_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    start_day = page * ADVENT_PAGE_SIZE + 1
    end_day = min(start_day + ADVENT_PAGE_SIZE - 1, event_days)

    embed = BotEmbed(
        title=f"{event['emoji']} {event['name']}",
        description=(
            f"Открыто: **{len(opened)}/{event_days}**\n"
            f"Следующее окошко: **{next_day if next_day <= event_days else '—'}**\n"
            + ("✅ Можно открыть!" if can_today else f"⏳ {reason}")
        ),
        color=0xe74c3c,
    )

    lines = []
    for day in range(start_day, end_day + 1):
        if day in opened:
            lines.append(f"✅ **{day}**")
        elif day == next_day and can_today:
            lines.append(f"🎁 **{day}**")
        else:
            lines.append(f"🔒 {day}")

    grid = ""
    for i in range(0, len(lines), 6):
        grid += "  ".join(lines[i:i+6]) + "\n"
    embed.add_field(name=f"Окошки {start_day}–{end_day}", value=grid or "—", inline=False)

    if next_day <= event_days:
        c, g, it = ADVENT_REWARDS.get(next_day, (50, 1, None))
        reward_str = f"🪙 {c} | 💎 {g}"
        if it:
            reward_str += f" | 🎁 {it}"
        embed.add_field(name=f"Награда за окошко {next_day}", value=reward_str, inline=False)

    embed.set_footer(text=f"Страница {page + 1}/{total_pages}")
    embed = await fix_embed_emojis(embed)
    return embed


