async def set_notification(user_id: int, notif_type: str, enabled: bool):
    """Включает/выключает уведомление. Создаёт запись, если её нет."""
    if notif_type not in NOTIFICATION_TYPES:
        return
    await bot.db.execute("""
        INSERT INTO user_notifications (user_id, notif_type, enabled)
        VALUES (?, ?, ?)
        ON CONFLICT(user_id, notif_type) DO UPDATE SET enabled = ?
    """, (user_id, notif_type, int(enabled), int(enabled)))
    await commit_if_needed()


async def can_send_notification(user_id: int, notif_type: str) -> bool:
    """Проверяет, включено ли уведомление и прошёл ли кулдаун."""
    async with bot.db.execute(
        "SELECT enabled, last_sent FROM user_notifications WHERE user_id = ? AND notif_type = ?",
        (user_id, notif_type)
    ) as c:
        row = await c.fetchone()

    if not row:
        return True  # по умолчанию включено, ещё не слали

    enabled, last_sent = row
    if not enabled:
        return False

    if last_sent:
        last = datetime.datetime.fromisoformat(last_sent)
        cooldown = NOTIFICATION_COOLDOWN_HOURS.get(notif_type, 24)
        if (datetime.datetime.now() - last).total_seconds() < cooldown * 3600:
            return False
    return True


async def mark_notification_sent(user_id: int, notif_type: str):
    """Отмечает, что уведомление отправлено (обновляет last_sent)."""
    now_iso = datetime.datetime.now().isoformat()
    async with db_transaction():
        await bot.db.execute("""
            INSERT INTO user_notifications (user_id, notif_type, enabled, last_sent)
            VALUES (?, ?, 1, ?)
            ON CONFLICT(user_id, notif_type) DO UPDATE SET last_sent = ?
        """, (user_id, notif_type, now_iso, now_iso))


async def send_dm_notification(user_id: int, notif_type: str, text: str, embed: discord.Embed = None) -> bool:
    """Пытается отправить ЛС. Возвращает True при успехе, False при Forbidden/NotFound."""
    try:
        user = bot.get_user(user_id)
        if user is None:
            user = await bot.fetch_user(user_id)
        if user is None:
            return False

        if embed:
            await user.send(embed=embed)
        else:
            await user.send(text)
        await mark_notification_sent(user_id, notif_type)
        await asyncio.sleep(0.25)  # мягкий throttle, чтобы не ловить rate limit
        return True
    except discord.Forbidden:
        # ЛС закрыты — сохраняем для эфемерной выдачи через /уведомления.
        # Одна запись на тип, чтобы повторные циклы не плодили дубли.
        title = NOTIFICATION_TYPES.get(notif_type, (notif_type, ""))[0]
        body = text or (embed.description if embed else "")
        async with db_transaction():
            await bot.db.execute(
                "DELETE FROM notification_fallback "
                "WHERE user_id = ? AND notif_type = ?",
                (user_id, notif_type),
            )
            await bot.db.execute(
                "INSERT INTO notification_fallback "
                "(user_id, notif_type, title, body) VALUES (?, ?, ?, ?)",
                (user_id, notif_type, title, body[:1000]),
            )
        return False
    except discord.NotFound:
        return False
    except discord.HTTPException:
        return False


async def delete_message_later(message, delay: int):
    """Удаляет публичное сообщение бота через delay секунд."""
    await asyncio.sleep(delay)
    try:
        await message.delete()
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        pass


async def buy_autocollector(user_id: int) -> tuple[bool, str]:
    """Покупка автосборщика. Возвращает (успех, сообщение)."""
    existing = await get_autocollector(user_id)
    if existing:
        return False, "❌ У тебя уже есть автосборщик."

    try:
        async with db_transaction():
            async with bot.db.execute(
                "SELECT 1 FROM autocollectors WHERE user_id = ?", (user_id,)
            ) as c:
                if await c.fetchone():
                    raise ValueError("У тебя уже есть автосборщик.")

            cur = await bot.db.execute(
                "UPDATE players SET gems = gems - ? "
                "WHERE user_id = ? AND gems >= ?",
                (AUTOCOLLECT_PRICE_GEMS, user_id, AUTOCOLLECT_PRICE_GEMS),
            )
            if cur.rowcount == 0:
                raise ValueError(f"Нужно 💎 {AUTOCOLLECT_PRICE_GEMS}.")

            await bot.db.execute(
                "INSERT INTO autocollectors (user_id, level, last_auto) VALUES (?, 1, ?)",
                (user_id, datetime.datetime.now().isoformat()),
            )
    except ValueError as e:
        return False, f"❌ {e}"

    return True, f"✅ Автосборщик куплен за 💎 {AUTOCOLLECT_PRICE_GEMS}! Теперь доход собирается раз в {AUTOCOLLECT_LEVELS[1][1]} ч."


async def upgrade_autocollector(user_id: int) -> tuple[bool, str]:
    """Улучшение автосборщика на следующий уровень."""
    existing = await get_autocollector(user_id)
    if not existing:
        return False, "❌ У тебя нет автосборщика. Сначала купи его."

    level, _ = existing
    if level >= AUTOCOLLECT_MAX_LEVEL:
        return False, f"❌ Автосборщик уже максимального уровня ({AUTOCOLLECT_MAX_LEVEL})."

    next_level = level + 1
    price, interval = AUTOCOLLECT_LEVELS[next_level]

    try:
        async with db_transaction():
            async with bot.db.execute(
                "SELECT level FROM autocollectors WHERE user_id = ?", (user_id,)
            ) as c:
                row = await c.fetchone()
            if not row or row[0] != level:
                raise ValueError("Данные изменились, попробуй снова.")

            cur = await bot.db.execute(
                "UPDATE players SET gems = gems - ? "
                "WHERE user_id = ? AND gems >= ?",
                (price, user_id, price),
            )
            if cur.rowcount == 0:
                raise ValueError(f"Нужно 💎 {price}.")

            await bot.db.execute(
                "UPDATE autocollectors SET level = ? WHERE user_id = ?",
                (next_level, user_id),
            )
    except ValueError as e:
        return False, f"❌ {e}"

    return True, f"✅ Автосборщик улучшен до {next_level} ур.! Теперь собирает раз в {interval} ч."


async def get_user_pets(user_id: int) -> list:
    """Список (pet_id, level, last_fed) всех питомцев игрока."""
    async with bot.db.execute(
        "SELECT pet_id, level, last_fed FROM user_pets_v2 WHERE user_id = ?", (user_id,)
    ) as c:
        return await c.fetchall()

def title_effect_bonus(title_name: str | None, effect_type: str) -> float:
    """Бонус титула по названию без обращения к БД."""
    if not title_name:
        return 0.0
    for title_id, (name, _req) in TITLES.items():
        if name == title_name:
            btype, bval = TITLE_BONUSES.get(title_id, (None, 0.0))
            return bval if btype == effect_type else 0.0
    return 0.0


async def get_title_bonus(user_id: int, effect_type: str) -> float:
    """Бонус от активного титула игрока для указанного эффекта."""
    async with bot.db.execute(
        "SELECT title FROM players WHERE user_id = ?", (user_id,)
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0.0
    return title_effect_bonus(row[0], effect_type)

async def get_total_bonus_line(user_id: int) -> str:
    """Возвращает эффективные множители дохода отдельно для монет и гемов."""
    status_bonus = await get_status_bonus(user_id)

    clan_bonus = 0.0
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0

    pet_coins = await get_pet_bonus(user_id, "income_coins")
    pet_gems = await get_pet_bonus(user_id, "income_gems")
    title_coins = await get_title_bonus(user_id, "income_coins")
    title_gems = await get_title_bonus(user_id, "income_gems")
    prestige_bonus = await get_prestige_bonus(user_id)
    collection_bonus = await get_collection_bonus(user_id)
    set_bonus = await get_set_bonus(user_id)

    mult_coins = (1 + status_bonus) * (1 + clan_bonus) * (
        1 + pet_coins + title_coins + prestige_bonus + collection_bonus + set_bonus
    )
    mult_gems = (1 + status_bonus) * (1 + clan_bonus) * (
        1 + pet_gems + title_gems + prestige_bonus + collection_bonus + set_bonus
    )
    coin_pct = int((mult_coins - 1) * 100)
    gem_pct = int((mult_gems - 1) * 100)

    parts = []
    if status_bonus > 0:
        parts.append(f"статус +{int(status_bonus*100)}%")
    if clan_bonus > 0:
        parts.append(f"клан +{int(clan_bonus*100)}%")
    if pet_coins or pet_gems:
        parts.append(f"питомец +{int(pet_coins*100)}%/+{int(pet_gems*100)}%")
    if title_coins or title_gems:
        parts.append(f"титул +{int(title_coins*100)}%/+{int(title_gems*100)}%")
    if prestige_bonus > 0:
        parts.append(f"престиж +{int(prestige_bonus*100)}%")
    if collection_bonus > 0:
        parts.append(f"коллекция +{int(collection_bonus*100)}%")
    if set_bonus > 0:
        parts.append(f"сеты +{int(set_bonus*100)}%")

    suffix = f" ({', '.join(parts)})" if parts else " (нет бонусов)"
    return f"**Монеты: +{coin_pct}%** | **Гемы: +{gem_pct}%**{suffix}"

async def get_total_bonus_percent(user_id: int) -> int:
    """Возвращает эффективный бонус к доходу монет в процентах."""
    status_bonus = await get_status_bonus(user_id)

    # клан
    clan_bonus = 0.0
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0

    # питомец, титул и престиж для монет
    pet_coins = await get_pet_bonus(user_id, "income_coins")
    title_coins = await get_title_bonus(user_id, "income_coins")
    prestige_bonus = await get_prestige_bonus(user_id)
    collection_bonus = await get_collection_bonus(user_id)
    set_bonus = await get_set_bonus(user_id)

    mult_coins = (1 + status_bonus) * (1 + clan_bonus) * (
        1 + pet_coins + title_coins + prestige_bonus + collection_bonus + set_bonus
    )
    return int((mult_coins - 1) * 100)


