async def get_prestige_bonus(user_id: int) -> float:
    points = await get_prestige_points(user_id)
    return min(points * PRESTIGE_BONUS_PER_POINT, PRESTIGE_BONUS_CAP)


def status_rank(upgrade_id: str) -> int:
    """Ранг статуса в линейке; -1 для не-статуса."""
    try:
        return STATUS_ORDER.index(upgrade_id)
    except ValueError:
        return -1


def best_status_bonus(status_ids) -> float:
    """Бонус лучшего статуса из набора."""
    best = 0.0
    for status_id in status_ids:
        bonus = STATUS_BONUSES.get(status_id, 0.0)
        if bonus > best:
            best = bonus
    return best


def format_status_expiry(value) -> str:
    if not value:
        return "бессрочно"
    try:
        parsed = datetime.datetime.fromisoformat(value)
    except (TypeError, ValueError):
        return str(value)
    return parsed.strftime("%d.%m.%Y %H:%M")


async def get_active_statuses(user_id: int) -> dict[str, str | None]:
    """Активные статусы пользователя: id -> expires_at (NULL = бессрочно)."""
    now_iso = datetime.datetime.now().isoformat()
    statuses = tuple(STATUS_BONUSES)
    placeholders = ",".join("?" for _ in statuses)
    try:
        async with bot.db.execute(
            f"SELECT upgrade_id, expires_at FROM player_upgrades "
            f"WHERE user_id = ? AND upgrade_id IN ({placeholders}) "
            f"AND (expires_at IS NULL OR datetime(expires_at) > datetime(?))",
            (user_id, *statuses, now_iso),
        ) as c:
            rows = await c.fetchall()
        return {row[0]: row[1] for row in rows}
    except aiosqlite.OperationalError:
        # Совместимость со старыми/упрощёнными схемами без expires_at.
        try:
            async with bot.db.execute(
                f"SELECT upgrade_id FROM player_upgrades "
                f"WHERE user_id = ? AND upgrade_id IN ({placeholders})",
                (user_id, *statuses),
            ) as c:
                rows = await c.fetchall()
            return {row[0]: None for row in rows}
        except aiosqlite.OperationalError:
            return {}


async def get_status_bonus(user_id: int) -> float:
    statuses = await get_active_statuses(user_id)
    return best_status_bonus(statuses.keys())


async def sync_status_bonus(user_id: int) -> float:
    bonus = await get_status_bonus(user_id)
    await bot.db.execute(
        "UPDATE players SET income_bonus = ? WHERE user_id = ?",
        (bonus, user_id),
    )
    await commit_if_needed()
    return bonus


async def grant_status_role(
    interaction: discord.Interaction, user_id: int, status_id: str
):
    guild = getattr(interaction, "guild", None)
    guild_id = getattr(interaction, "guild_id", None)
    if not guild or not guild_id:
        return
    settings = await get_settings(guild_id)
    role_id = settings.get("status_roles", {}).get(status_id)
    if not role_id:
        return
    member = guild.get_member(user_id)
    role = guild.get_role(role_id)
    if not member or not role:
        return
    try:
        await member.add_roles(
            role, reason=f"Статус {STATUS_NAMES.get(status_id, status_id)}"
        )
    except discord.HTTPException:
        pass


async def remove_status_role(user_id: int, status_id: str):
    for guild in getattr(bot, "guilds", []):
        try:
            settings = await get_settings(guild.id)
            role_id = settings.get("status_roles", {}).get(status_id)
            if not role_id:
                continue
            member = guild.get_member(user_id)
            role = guild.get_role(role_id)
            if member and role:
                await member.remove_roles(role, reason="Временный статус истёк")
        except Exception:
            log.debug(
                "STATUS_EXPIRY: не удалось снять роль %s у %s",
                status_id,
                user_id,
            )


async def purchase_status(
    user_id: int, status_id: str, days: int
) -> tuple[bool, str]:
    if status_id not in STATUS_BONUSES:
        return False, "❌ Неизвестный статус."
    if days not in STATUS_DURATIONS:
        return False, "❌ Неверный срок статуса."
    price = status_price(status_id, days)
    if price is None:
        return False, "❌ Неверная цена статуса."
    name = STATUS_NAMES.get(status_id, status_id)

    try:
        async with db_transaction():
            async with bot.db.execute(
                "SELECT gems FROM players WHERE user_id = ?", (user_id,)
            ) as c:
                row = await c.fetchone()
            if not row:
                raise ValueError("❌ Профиль не найден.")
            gems = row[0] or 0
            if gems < price:
                raise ValueError(
                    f"❌ Нужно 💎 {price}, у тебя {gems}."
                )

            active = await get_active_statuses(user_id)
            owned_rank = max(
                (status_rank(item) for item in active),
                default=-1,
            )
            if status_rank(status_id) < owned_rank:
                best = max(active, key=status_rank)
                raise ValueError(
                    f"❌ У тебя активен **{STATUS_NAMES.get(best, best)}**. "
                    "Статус ниже по линейке покупать нельзя."
                )

            now = datetime.datetime.now()
            async with bot.db.execute(
                "SELECT expires_at FROM player_upgrades "
                "WHERE user_id = ? AND upgrade_id = ?",
                (user_id, status_id),
            ) as c:
                current = await c.fetchone()
            base = now
            if current and current[0]:
                try:
                    current_expiry = datetime.datetime.fromisoformat(
                        current[0]
                    )
                except (TypeError, ValueError):
                    current_expiry = None
                if current_expiry and current_expiry > now:
                    base = current_expiry
            new_expiry = base + datetime.timedelta(days=days)

            cur = await bot.db.execute(
                "UPDATE players SET gems = gems - ? "
                "WHERE user_id = ? AND gems >= ?",
                (price, user_id, price),
            )
            if cur.rowcount == 0:
                raise ValueError("❌ Недостаточно гемов (баланс изменился).")

            await bot.db.execute("""
                INSERT INTO player_upgrades
                    (user_id, upgrade_id, level, purchased_at, expires_at)
                VALUES (?, ?, 1, CURRENT_TIMESTAMP, ?)
                ON CONFLICT(user_id, upgrade_id) DO UPDATE SET
                    expires_at = excluded.expires_at,
                    purchased_at = CURRENT_TIMESTAMP
            """, (user_id, status_id, new_expiry.isoformat()))
            await sync_status_bonus(user_id)
    except ValueError as exc:
        return False, str(exc)

    return True, (
        f"✅ **{name}** активирован до "
        f"`{format_status_expiry(new_expiry.isoformat())}`. "
        f"Списано 💎 {price}."
    )


async def expire_statuses() -> list[tuple[int, str]]:
    """Удаляет истёкшие статусы и пересчитывает income_bonus."""
    now_iso = datetime.datetime.now().isoformat()
    statuses = tuple(STATUS_BONUSES)
    placeholders = ",".join("?" for _ in statuses)
    async with db_transaction():
        async with bot.db.execute(
            f"SELECT user_id, upgrade_id FROM player_upgrades "
            f"WHERE upgrade_id IN ({placeholders}) "
            f"AND expires_at IS NOT NULL "
            f"AND datetime(expires_at) <= datetime(?)",
            (*statuses, now_iso),
        ) as c:
            expired = await c.fetchall()
        if not expired:
            return []
        await bot.db.execute(
            f"DELETE FROM player_upgrades "
            f"WHERE upgrade_id IN ({placeholders}) "
            f"AND expires_at IS NOT NULL "
            f"AND datetime(expires_at) <= datetime(?)",
            (*statuses, now_iso),
        )
        for user_id in {row[0] for row in expired}:
            await sync_status_bonus(user_id)

    for user_id, status_id in expired:
        await remove_status_role(user_id, status_id)
    return expired


async def get_collection_count(user_id: int) -> int:
    async with bot.db.execute(
        "SELECT COUNT(*) FROM player_collection pc "
        "JOIN items i ON i.id = pc.item_id "
        "WHERE pc.user_id = ? AND i.id LIKE '%\\_gen' ESCAPE '\\'",
        (user_id,),
    ) as c:
        return (await c.fetchone())[0] or 0


async def get_collection_bonus(user_id: int) -> float:
    return (await get_collection_count(user_id)) * COLLECTION_BONUS_PER_ITEM


def get_set_tier(set_id: str, count: int) -> tuple[int, float]:
    """Возвращает лучший достигнутый порог сета и его бонус."""
    for threshold, bonus in SET_DEFINITIONS[set_id]["tiers"]:
        if count >= threshold:
            return threshold, bonus
    return 0, 0.0


def compute_set_synergy(rows, grid_size: int) -> dict:
    """Считает бонусы сетов по раскладке энергостанции.

    rows: [(slot, item_id), ...] только из location='profile'.
    """
    set_items = {set_id: set() for set_id in SET_DEFINITIONS}
    slot_sets = {}

    for slot, item_id in rows:
        set_id = ITEM_SET.get(item_id)
        if not set_id:
            continue
        set_items[set_id].add(item_id)
        slot_sets[int(slot)] = set_id

    set_counts = {set_id: len(items) for set_id, items in set_items.items()}
    set_tiers = {}
    set_bonus = 0.0
    for set_id, count in set_counts.items():
        threshold, bonus = get_set_tier(set_id, count)
        set_tiers[set_id] = (threshold, bonus)
        set_bonus += bonus

    width = max(1, int(grid_size ** 0.5))
    adjacency_pairs = 0
    for slot, set_id in slot_sets.items():
        right = slot + 1
        if right < grid_size and slot % width != width - 1:
            if slot_sets.get(right) == set_id:
                adjacency_pairs += 1
        down = slot + width
        if down < grid_size and slot_sets.get(down) == set_id:
            adjacency_pairs += 1

    full_rows = 0
    for start in range(0, grid_size, width):
        row_sets = [
            slot_sets.get(slot)
            for slot in range(start, min(start + width, grid_size))
        ]
        if row_sets and all(row_sets) and len(set(row_sets)) == 1:
            full_rows += 1

    adjacency_bonus = min(adjacency_pairs * SET_ADJACENCY_BONUS, SET_ADJACENCY_MAX)
    floor_bonus = min(full_rows * SET_FLOOR_BONUS, SET_FLOOR_MAX)
    total = min(set_bonus + adjacency_bonus + floor_bonus, SET_TOTAL_MAX)

    return {
        "set_counts": set_counts,
        "set_tiers": set_tiers,
        "set_bonus": set_bonus,
        "adjacency_pairs": adjacency_pairs,
        "adjacency_bonus": adjacency_bonus,
        "full_rows": full_rows,
        "floor_bonus": floor_bonus,
        "total": total,
    }


async def get_set_synergy_details(user_id: int) -> dict:
    grid_size = await get_grid_size(user_id)
    async with bot.db.execute(
        "SELECT slot, item_id FROM inventory "
        "WHERE user_id = ? AND location = 'profile'",
        (user_id,),
    ) as c:
        rows = await c.fetchall()
    return compute_set_synergy(rows, grid_size)


async def get_set_bonus(user_id: int) -> float:
    details = await get_set_synergy_details(user_id)
    return details["total"]


def prestige_required_total(points: int) -> int:
    """Сколько всего монет нужно для получения N очков престижа."""
    points = max(0, int(points))
    return (
        points * PRESTIGE_BASE_REQUIREMENT
        + PRESTIGE_STEP_REQUIREMENT * points * (points - 1) // 2
    )


def prestige_point_cost(points_earned: int) -> int:
    """Стоимость следующего очка с учётом уже полученных."""
    return PRESTIGE_BASE_REQUIREMENT + max(0, int(points_earned)) * PRESTIGE_STEP_REQUIREMENT


def prestige_gain_from_lifetime(lifetime: int, existing_points: int) -> int:
    """Сколько новых очков даёт текущее производство с учётом старых очков."""
    remaining = max(0, int(lifetime or 0))
    points = max(0, int(existing_points or 0))
    gain = 0
    while remaining >= prestige_point_cost(points):
        remaining -= prestige_point_cost(points)
        points += 1
        gain += 1
    return gain


def prestige_points_from_lifetime(total: int) -> int:
    """Сколько всего очков заработано при данном объёме производства."""
    return prestige_gain_from_lifetime(total, 0)


async def calculate_prestige_gain(user_id: int) -> int:
    async with bot.db.execute(
        "SELECT lifetime_production, prestige_points FROM players WHERE user_id = ?",
        (user_id,),
    ) as c:
        row = await c.fetchone()
    if not row:
        return 0
    total, points = row
    return prestige_gain_from_lifetime(total or 0, points or 0)


async def do_prestige(user_id: int, guild_id: int | None = None) -> tuple[bool, str, int, int]:
    settings = await get_settings(guild_id) if guild_id else {
        "start_coins": DEFAULT_START_COINS,
    }
    start_coins = settings["start_coins"]
    points = await get_prestige_points(user_id)
    released_bids = 0

    try:
        async with db_transaction():
            async with bot.db.execute(
                "SELECT lifetime_production, prestige_points FROM players WHERE user_id = ?",
                (user_id,),
            ) as c:
                row = await c.fetchone()
            if not row:
                raise ValueError("Профиль не найден.")

            total, points = row
            points = points or 0
            gain = prestige_gain_from_lifetime(total or 0, points)
            if gain <= 0:
                need = prestige_point_cost(points) - (total or 0)
                raise ValueError(
                    f"Нужно ещё 🪙 {max(0, need)} производства для "
                    f"следующего очка."
                )

            for label, sql in (
                ("вклад", "SELECT 1 FROM bank_deposits WHERE user_id = ?"),
                (
                    "кредит",
                    "SELECT 1 FROM bank_loans WHERE user_id = ? "
                    "AND COALESCE(status, 'active') = 'active'",
                ),
                (
                    "ордера",
                    "SELECT 1 FROM market_orders WHERE user_id = ? "
                    "AND status = 'active'",
                ),
            ):
                async with bot.db.execute(sql, (user_id,)) as c:
                    if await c.fetchone():
                        raise ValueError(
                            f"Сначала закрой {label}: перерождение не должно "
                            "терять активные обязательства."
                        )

            # Снимаем ставки игрока на чужих лотах: после сброса
            # он не должен остаться лидером аукциона с обнулённым балансом.
            released_bids, _refunded = await release_active_auction_bids(user_id)

            # Закрываем активные лоты игрока и возвращаем ставки.
            async with bot.db.execute(
                "SELECT id, current_bidder, current_bid FROM auctions "
                "WHERE seller_id = ? AND status = 'active'",
                (user_id,),
            ) as c:
                lots = await c.fetchall()
            for aid, bidder, bid in lots:
                if bidder and bid:
                    await bot.db.execute(
                        "UPDATE players SET coins = coins + ? WHERE user_id = ?",
                        (bid, bidder),
                    )
                await bot.db.execute(
                    "DELETE FROM auction_bids WHERE auction_id = ?", (aid,)
                )
                await bot.db.execute("DELETE FROM auctions WHERE id = ?", (aid,))

            now_iso = datetime.datetime.now().isoformat()
            try:
                await bot.db.execute(
                    "DELETE FROM player_upgrades WHERE user_id = ? "
                    "AND upgrade_id IN ('vip','gold','platinum','diamond') "
                    "AND expires_at IS NOT NULL "
                    "AND datetime(expires_at) <= datetime(?)",
                    (user_id, now_iso),
                )
            except aiosqlite.OperationalError:
                # Совместимость с очень старыми/упрощёнными схемами.
                pass
            active_statuses = await get_active_statuses(user_id)
            status_bonus = best_status_bonus(active_statuses.keys())

            await bot.db.execute("""
                UPDATE players SET
                    coins = ?,
                    grid_size = 9,
                    storage_size = 36,
                    income_bonus = ?,
                    catalysts = 0,
                    lifetime_production = 0,
                    prestige_points = prestige_points + ?,
                    daily_quest_date = NULL,
                    daily_quest_progress = '{}',
                    daily_quest_claimed = '[]',
                    last_collected = CURRENT_TIMESTAMP,
                    last_gem_collected = CURRENT_TIMESTAMP,
                    last_tax_time = CURRENT_TIMESTAMP
                WHERE user_id = ?
            """, (start_coins, status_bonus, gain, user_id))

            await bot.db.execute("DELETE FROM inventory WHERE user_id = ?", (user_id,))
            await bot.db.execute(
                "DELETE FROM market_orders WHERE user_id = ?", (user_id,)
            )
            # Сетки сбрасываются вместе с энергостанцией, а активные
            # временные статусы сохраняются до своего expires_at.
            await bot.db.execute(
                "DELETE FROM player_upgrades WHERE user_id = ? "
                "AND (upgrade_id IS NULL OR upgrade_id NOT IN "
                "('vip','gold','platinum','diamond'))",
                (user_id,),
            )
            await bot.db.execute(
                "DELETE FROM bank_deposits WHERE user_id = ?", (user_id,)
            )
            await bot.db.execute(
                "DELETE FROM bank_loans WHERE user_id = ?", (user_id,)
            )
    except ValueError as e:
        return False, f"❌ {e}", 0, points

    await add_season_xp(user_id, season_xp_amount("prestige"), guild_id, action="prestige")
    new_points = points + gain
    bid_note = ""
    if released_bids:
        bid_note = (
            f"\n🏛️ Сняты активные ставки на аукционах: **{released_bids}**."
        )
    return (
        True,
        f"{get_emoji('_rebirth')} Перерождение завершено! Получено **{gain}** очков престижа.\n"
        f"Всего очков: **{new_points}** "
        f"(+{int(min(new_points * PRESTIGE_BONUS_PER_POINT, PRESTIGE_BONUS_CAP) * 100)}% к доходу)."
        f"{bid_note}",
        gain,
        new_points,
    )


