async def build_main_embed(interaction: discord.Interaction) -> discord.Embed:
    user_id = interaction.user.id
    guild_id = interaction.guild_id
    settings = await get_settings(guild_id)
    compact = await is_accessibility_mode(user_id)
    await collect_income(user_id, guild_id)

    grid_size, bonus, gems, coins = await get_player_stats(user_id, guild_id)
    per_sec_coins, per_sec_gems = await get_per_second_income(user_id)

    custom = settings["custom_emojis"]
    coin = custom.get("_coin", str(BOT_BTN_EMOJIS.get("_coin", "🪙")))
    gem = custom.get("_gem", str(BOT_BTN_EMOJIS.get("_gem", "💎")))
    castle = custom.get("_castle", str(BOT_BTN_EMOJIS.get("_castle", "⚡")))

    parts = []
    if per_sec_coins > 0:
        parts.append(f"{coin} {per_sec_coins * 3600:.2f}/час")
    if per_sec_gems > 0:
        parts.append(f"{gem} {per_sec_gems * 3600:.4f}/час")
    income_str = (
        " | ".join(parts)
        if parts
        else "нет генераторов · купи первый в «Магазине»"
    )

    # --- Собираем все бонусы ---
    # статус (активные временные статусы)
    status_bonus = bonus or 0.0

    # клан
    clan_bonus = 0.0
    clan = await get_clan(user_id)
    if clan:
        clan_bonus = clan[4] or 0.0

    # питомец
    pet_coins = await get_pet_bonus(user_id, "income_coins")
    pet_gems = await get_pet_bonus(user_id, "income_gems")
    pet_bonus = max(pet_coins, pet_gems)  # для отображения общего

    # титул
    title_coins = await get_title_bonus(user_id, "income_coins")
    title_gems = await get_title_bonus(user_id, "income_gems")
    title_bonus = max(title_coins, title_gems)

    # --- Формируем строку бонусов ---
    total_pct = await get_total_bonus_percent(user_id)
    season = await get_season_data(user_id)
    embed = BotEmbed(
        title=f"{castle} {settings['bot_name']} — Энергостанция {interaction.user.name}",
        description="Выбери раздел кнопками ниже.",
        color=0x00ff00
    )
    if not compact:
        embed.set_thumbnail(url=interaction.user.display_avatar.url)
    embed.add_field(
        name=f"Кошелёк ({settings['currency_coins']}/{settings['currency_gems']})",
        value=f"{coin} {coins} | {gem} {gems}",
        inline=False
    )
    embed.add_field(
        name="Доход",
        value=f"{income_str}\n-# {INCOME_HINT}",
        inline=False,
    )
    embed.add_field(name="Бонус", value=f"+{total_pct}%", inline=True)
    embed.add_field(name="Сетка", value=f"{grid_size} слотов", inline=True)
    season_value = (
        f"Ур. **{season['level']}/{SEASON_LEVELS}** · {season['days_left']} дн."
        if settings.get("battlepass_enabled", True)
        else "Отключён"
    )
    embed.add_field(name="Сезон", value=season_value, inline=True)
    onboarding_done = await get_onboarding_progress(user_id)
    if len(onboarding_done) < len(ONBOARDING_STEPS):
        _next_step, next_data = get_next_onboarding_step(onboarding_done)
        embed.add_field(
            name="Первые шаги",
            value=(
                f"**{len(onboarding_done)}/{len(ONBOARDING_STEPS)}** · "
                f"следующее: {next_data[0] if next_data else 'готово'}"
            ),
            inline=False,
        )
    else:
        cache = getattr(bot, "_onboarding_complete_cache", None)
        if cache is None:
            cache = set()
            bot._onboarding_complete_cache = cache
        cache.add(user_id)
    embed = await fix_embed_emojis(embed)
    return embed

