class ClanTransferModal(discord.ui.Modal, title="Передать лидерство"):
    user_id = discord.ui.TextInput(label="ID нового лидера", required=True)
    confirm = discord.ui.TextInput(label="Введите ДА", required=True)
    def __init__(self, author_id: int, clan_id: int):
        super().__init__()
        self.author_id, self.clan_id = author_id, clan_id
    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        if self.confirm.value.strip().upper() != "ДА":
            return await interaction.followup.send("❌ Отменено.", ephemeral=True)
        try:
            target = int(self.user_id.value)
        except ValueError:
            return await interaction.followup.send("❌ Неверный ID.", ephemeral=True)
        if target == self.author_id:
            return await interaction.followup.send(
                "❌ Нельзя передать лидерство себе.", ephemeral=True
            )
        try:
            async with db_transaction():
                role = await get_clan_role(self.author_id, self.clan_id)
                if role != "leader":
                    raise ValueError("❌ Только лидер может передать лидерство.")
                target_role = await get_clan_role(target, self.clan_id)
                if target_role == "none":
                    raise ValueError("❌ Игрок не в клане.")
                if target_role == "leader":
                    raise ValueError("❌ Он уже лидер.")
                cur = await bot.db.execute(
                    "UPDATE clan_members SET role = 'member' "
                    "WHERE user_id = ? AND clan_id = ? AND role = 'leader'",
                    (self.author_id, self.clan_id),
                )
                if cur.rowcount == 0:
                    raise ValueError("❌ Ты уже не лидер клана.")
                cur = await bot.db.execute(
                    "UPDATE clan_members SET role = 'leader' "
                    "WHERE user_id = ? AND clan_id = ? AND role = ?",
                    (target, self.clan_id, target_role),
                )
                if cur.rowcount == 0:
                    raise ValueError("❌ Не удалось передать лидерство.")
                await bot.db.execute(
                    "UPDATE clans SET leader_id = ? WHERE id = ?",
                    (target, self.clan_id),
                )
        except ValueError as exc:
            await interaction.followup.send(str(exc), ephemeral=True)
            return
        await log_clan(self.clan_id, "transfer", f"Лидерство → <@{target}>")
        await interaction.followup.send(
            f"👑 Лидерство передано <@{target}>.", ephemeral=True
        )

class ClanDisbandModal(discord.ui.Modal, title="Распустить клан"):
    confirm = discord.ui.TextInput(label="Введите УДАЛИТЬ", required=True)

    def __init__(self, author_id: int, clan_id: int):
        super().__init__()
        self.author_id, self.clan_id = author_id, clan_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        if self.confirm.value.strip() != "УДАЛИТЬ":
            return await interaction.followup.send("❌ Отменено.", ephemeral=True)

        try:
            async with db_transaction():
                role = await get_clan_role(self.author_id, self.clan_id)
                if role != "leader":
                    raise ValueError("❌ Распустить клан может только лидер.")
                async with bot.db.execute(
                    "SELECT treasury FROM clans WHERE id = ?", (self.clan_id,)
                ) as c:
                    row = await c.fetchone()
                if not row:
                    raise ValueError("❌ Клан уже не существует.")
                treasury = row[0] or 0

                # 1. Закрываем активные войны клана (до удаления)
                await bot.db.execute(
                    "UPDATE clan_wars SET status = 'finished', "
                    "winner_id = NULL, end_time = ? "
                    "WHERE (clan1_id = ? OR clan2_id = ?) "
                    "AND status = 'active'",
                    (
                        datetime.datetime.now().isoformat(),
                        self.clan_id,
                        self.clan_id,
                    ),
                )

                # 2. Возвращаем сундук участникам (поровну)
                members = await get_clan_members(self.clan_id)
                if members and treasury > 0:
                    share = treasury // len(members)
                    if share > 0:
                        await bot.db.execute(
                            "UPDATE players SET coins = coins + ? "
                            "WHERE user_id IN (SELECT user_id FROM "
                            "clan_members WHERE clan_id = ?)",
                            (share, self.clan_id),
                        )

                # 3. Удаляем всё, что связано с кланом
                await bot.db.execute(
                    "DELETE FROM clan_inventory WHERE clan_id = ?",
                    (self.clan_id,),
                )
                await bot.db.execute(
                    "DELETE FROM clan_members WHERE clan_id = ?",
                    (self.clan_id,),
                )
                await bot.db.execute(
                    "DELETE FROM clan_invites WHERE clan_id = ?",
                    (self.clan_id,),
                )
                await bot.db.execute(
                    "DELETE FROM clan_quests WHERE clan_id = ?",
                    (self.clan_id,),
                )
                await bot.db.execute(
                    "DELETE FROM clan_wars "
                    "WHERE clan1_id = ? OR clan2_id = ?",
                    (self.clan_id, self.clan_id),
                )
                await bot.db.execute(
                    "DELETE FROM clans WHERE id = ?", (self.clan_id,)
                )
        except ValueError as exc:
            await interaction.followup.send(str(exc), ephemeral=True)
            return

        await interaction.followup.send("💀 Клан распущен.", ephemeral=True)

async def open_clan_buy_select(interaction: discord.Interaction, author_id: int, clan_id: int, page: int = 0):
    async with bot.db.execute("SELECT id, name, price, emoji FROM items WHERE buyable = 1 ORDER BY price ASC") as c:
        rows = await c.fetchall()
    total_pages = max(1, (len(rows) + 9) // 10)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page*10:page*10+10]
    options = [
        discord.SelectOption(
            label=f"{name} — {price} монет",
            value=item_id,
            emoji=parse_emoji_safe(emoji),
        )
        for item_id, name, price, emoji in chunk
    ]
    embed = BotEmbed(title="🛒 Купить для клана", description=f"Страница {page+1}/{total_pages}", color=0xf1c40f)
    await interaction.edit_original_response(embed=embed, view=ClanBuySelectView(author_id, clan_id, options, page, total_pages))

class ClanBuySelectView(SafeView):
    feature_key = "clans"
    def __init__(self, author_id: int, clan_id: int, options, page: int, total_pages: int):
        super().__init__(timeout=120)
        self.author_id, self.clan_id, self.page, self.total_pages = author_id, clan_id, page, total_pages
        self.add_item(make_select("Выбери предмет", options, self.item_select, row=0))
        if total_pages > 1:
            p = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1); p.callback = self.prev; self.add_item(p)
            n = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1); n.callback = self.next; self.add_item(n)
        b = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.danger, row=2); b.callback = self.back; self.add_item(b)
    async def interaction_check(self, i):
        return await self.check_owner(i)
    async def item_select(self, interaction):
        item_id = interaction.data["values"][0]
        await interaction.response.defer()

        role = await get_clan_role(self.author_id, self.clan_id)
        if not has_clan_permission(role, "buy"):
            return await interaction.followup.send("❌ Недостаточно прав.", ephemeral=True)

        async with bot.db.execute("SELECT name, price FROM items WHERE id = ?", (item_id,)) as c:
            row = await c.fetchone()
        if not row:
            return await interaction.followup.send("❌ Предмет не найден.", ephemeral=True)
        name, price = row

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT treasury FROM clans WHERE id = ?", (self.clan_id,)
                ) as c:
                    clan_row = await c.fetchone()
                treasury = (clan_row[0] if clan_row else 0) or 0
                if treasury < price:
                    raise ValueError("В сундуке клана недостаточно монет.")

                async with bot.db.execute(
                    "SELECT slot FROM clan_inventory WHERE clan_id = ?", (self.clan_id,)
                ) as c:
                    used = {r[0] for r in await c.fetchall()}
                free = [s for s in range(36) if s not in used]
                if not free:
                    raise ValueError("В клановой сетке нет места.")

                await bot.db.execute(
                    "INSERT INTO clan_inventory (clan_id, slot, item_id) VALUES (?, ?, ?)",
                    (self.clan_id, free[0], item_id),
                )
                cur = await bot.db.execute(
                    "UPDATE clans SET treasury = treasury - ? "
                    "WHERE id = ? AND treasury >= ?",
                    (price, self.clan_id, price),
                )
                if cur.rowcount == 0:
                    raise ValueError("В сундуке клана недостаточно монет.")
        except ValueError as e:
            return await interaction.followup.send(f"❌ {e}", ephemeral=True)

        await log_clan(self.clan_id, "buy", f"{name} за {price} из сундука")
        await add_clan_xp(self.clan_id, max(1, price // 100))
        await interaction.followup.send(
            f"✅ Куплено **{name}** для клана за 🪙 {price} из сундука.",
            ephemeral=True,
        )
    async def prev(self, i): await i.response.defer(); await open_clan_buy_select(i, self.author_id, self.clan_id, self.page-1)
    async def next(self, i): await i.response.defer(); await open_clan_buy_select(i, self.author_id, self.clan_id, self.page+1)
    async def back(self, i):
        await i.response.defer()
        clan = await get_clan(self.author_id)
        embed = await build_clan_embed(i, clan)
        await i.edit_original_response(embed=embed, view=ClanMenuView(self.author_id, self.clan_id))

CLAN_QUESTS = [
    ("synthesize", "Сделать 20 синтезов", 20, 500),
    ("buy", "Купить 10 генераторов", 10, 300),
    ("raid", "Совершить 5 рейдов", 5, 400),
    ("war", "Выиграть войну", 1, 1000),
]

async def get_or_create_clan_quests(clan_id: int):
    week_key = str(datetime.date.today().isocalendar()[:2])
    async with bot.db.execute(
        "SELECT id, quest_type, progress, target, reward, completed, week_start "
        "FROM clan_quests WHERE clan_id = ?",
        (clan_id,),
    ) as c:
        rows = await c.fetchall()

    if rows and all((r[6] or "") == week_key for r in rows):
        return [r[:6] for r in rows]

    # Новая неделя (или первый запуск) — пересоздаём квесты.
    await bot.db.execute("DELETE FROM clan_quests WHERE clan_id = ?", (clan_id,))
    for qt, desc, target, reward in CLAN_QUESTS:
        await bot.db.execute(
            "INSERT INTO clan_quests "
            "(clan_id, quest_type, target, reward, week_start) "
            "VALUES (?, ?, ?, ?, ?)",
            (clan_id, qt, target, reward, week_key),
        )
    await commit_if_needed()

    async with bot.db.execute(
        "SELECT id, quest_type, progress, target, reward, completed, week_start "
        "FROM clan_quests WHERE clan_id = ?",
        (clan_id,),
    ) as c:
        rows = await c.fetchall()
    return [r[:6] for r in rows]

async def build_clan_quests_embed(clan_id: int):
    rows = await get_or_create_clan_quests(clan_id)
    embed = BotEmbed(title="📜 Клановые квесты", description="Недельные задания для всего клана", color=0x3498db)
    for qid, qt, prog, target, reward, completed in rows:
        desc = next(d for t, d, _, _ in CLAN_QUESTS if t == qt)
        status = "✅ Выполнено" if completed else "⏳ В процессе"
        embed.add_field(name=desc, value=f"Прогресс: {prog}/{target}\nНаграда: 🪙 {reward}\n{status}", inline=False)
    embed = await fix_embed_emojis(embed)
    return embed

async def update_clan_quest(clan_id: int, quest_type: str, amount: int = 1):
    async with bot.db.execute("SELECT id, progress, target, reward, completed FROM clan_quests WHERE clan_id = ? AND quest_type = ?", (clan_id, quest_type)) as c:
        row = await c.fetchone()
    if not row or row[4]: return
    qid, prog, target, reward, _ = row
    prog = min(prog + amount, target)
    completed = prog >= target
    await bot.db.execute("UPDATE clan_quests SET progress = ?, completed = ? WHERE id = ?", (prog, int(completed), qid))
    if completed:
        await bot.db.execute("UPDATE clans SET treasury = treasury + ? WHERE id = ?", (reward, clan_id))
        await log_clan(clan_id, "quest_complete", f"Тип: {quest_type}, +{reward} в сундук")
        await add_clan_xp(clan_id, 50)
    await commit_if_needed()

class CreateClanModal(discord.ui.Modal, title="Создание клана"):
    name = discord.ui.TextInput(label="Название клана", required=True)

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        cost = 500

        # Проверка баланса
        async with bot.db.execute("SELECT coins FROM players WHERE user_id = ?", (self.author_id,)) as c:
            row = await c.fetchone()
        coins = row[0] if row else 0
        if coins < cost:
            return await interaction.followup.send(f"❌ Нужно {cost} монет для создания клана.", ephemeral=True)

        # Проверка, что не в клане
        existing = await get_clan(self.author_id)
        if existing:
            return await interaction.followup.send("❌ Ты уже в клане.", ephemeral=True)

        # Проверка названия
        clan_name = self.name.value.strip()
        if len(clan_name) < 3 or len(clan_name) > 32:
            return await interaction.followup.send("❌ Название должно быть от 3 до 32 символов.", ephemeral=True)

        # Создание клана
        try:
            async with db_transaction():
                if await get_clan(self.author_id):
                    raise ValueError("Ты уже в клане.")
                cur = await bot.db.execute(
                    "UPDATE players SET coins = coins - ? "
                    "WHERE user_id = ? AND coins >= ?",
                    (cost, self.author_id, cost),
                )
                if cur.rowcount == 0:
                    raise ValueError(f"Нужно {cost} монет для создания клана.")
                cursor = await bot.db.execute(
                    "INSERT INTO clans (name, leader_id, treasury) "
                    "VALUES (?, ?, 0)",
                    (clan_name, self.author_id),
                )
                clan_id = cursor.lastrowid
                await bot.db.execute(
                    "INSERT INTO clan_members (user_id, clan_id, role) "
                    "VALUES (?, ?, 'leader')",
                    (self.author_id, clan_id),
                )
            await interaction.followup.send(
                f"✅ Клан **{clan_name}** создан за {cost} монет!", ephemeral=True
            )
            await update_story_quests(self.author_id, "clan_join", 1)
        except ValueError as e:
            await interaction.followup.send(f"❌ {e}", ephemeral=True)
        except Exception as e:
            await interaction.followup.send(f"❌ Ошибка: `{e}`", ephemeral=True)


class DepositClanModal(discord.ui.Modal, title="Пополнить сундук клана"):
    amount = discord.ui.TextInput(label="Сумма (монеты)", default="100", required=True)

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        try:
            amt = int(self.amount.value)
            if amt <= 0: raise ValueError
        except ValueError:
            return await interaction.followup.send("❌ Неверная сумма.", ephemeral=True)

        clan = await get_clan(self.author_id)
        if not clan:
            return await interaction.followup.send("❌ Ты не в клане.", ephemeral=True)

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT coins FROM players WHERE user_id = ?", (self.author_id,)
                ) as c:
                    coins = (await c.fetchone())[0]
                if coins < amt:
                    raise ValueError("Недостаточно монет.")

                cur = await bot.db.execute(
                    "UPDATE players SET coins = coins - ? "
                    "WHERE user_id = ? AND coins >= ?",
                    (amt, self.author_id, amt),
                )
                if cur.rowcount == 0:
                    raise ValueError("Недостаточно монет (баланс изменился).")

                await bot.db.execute(
                    "UPDATE clans SET treasury = treasury + ? WHERE id = ?",
                    (amt, clan[0]),
                )
        except ValueError as e:
            return await interaction.followup.send(f"❌ {e}", ephemeral=True)

        await update_quest_progress(self.author_id, "donate_clan")
        await add_clan_xp(clan[0], max(1, amt // 100))
        await interaction.followup.send(f"✅ В сундук клана внесено 🪙 {amt}.", ephemeral=True)

# ============================================================
#  ⚔️ РЕЙДЫ И ОТРЯДЫ
# ============================================================

def _parse_db_time(value):
    """Парсит дату из SQLite (CURRENT_TIMESTAMP или ISO) без падений."""
    if not value:
        return None
    if isinstance(value, datetime.datetime):
        return value
    text = str(value).strip()
    if not text:
        return None
    try:
        return datetime.datetime.fromisoformat(text)
    except ValueError:
        pass
    for fmt in ("%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.datetime.strptime(text, fmt)
        except ValueError:
            continue
    return None


async def _handle_modal_error(interaction: discord.Interaction, error: Exception):
    """Показывает понятную ошибку, если модалка упала до/после defer."""
    log.exception("Ошибка модального окна рейда", exc_info=error)
    try:
        if interaction.response.is_done():
            await interaction.followup.send(
                "❌ Ошибка. Попробуй ещё раз.", ephemeral=True
            )
        else:
            await interaction.response.send_message(
                "❌ Ошибка. Попробуй ещё раз.", ephemeral=True
            )
    except discord.HTTPException:
        pass


def party_member_ids(party) -> list[int]:
    """Достаёт участников отряда из строки raid_parties."""
    if not party:
        return []
    members = []
    for value in (party[1], party[2], party[3]):
        if value and value not in members:
            members.append(value)
    return members


async def cleanup_expired_raid_parties():
    """Удаляет отряды, которые не проявляли активности дольше TTL."""
    await cleanup_expired_raid_invites()
    ttl = datetime.timedelta(minutes=RAID_PARTY_TTL_MINUTES)
    cutoff_local = datetime.datetime.now() - ttl
    cutoff_utc = datetime.datetime.now(datetime.timezone.utc) - ttl

    async with bot.db.execute(
        "SELECT id, created_at, updated_at FROM raid_parties"
    ) as c:
        rows = await c.fetchall()

    expired = []
    for party_id, created_at, updated_at in rows:
        # updated_at пишем локальным временем. created_at у старых строк
        # заполняется SQLite как UTC — обрабатываем его отдельно.
        last_seen = _parse_db_time(updated_at)
        if last_seen is not None:
            is_expired = last_seen < cutoff_local
        else:
            created = _parse_db_time(created_at)
            if created is None:
                is_expired = True
            else:
                is_expired = created.replace(
                    tzinfo=datetime.timezone.utc
                ) < cutoff_utc
        if is_expired:
            expired.append(party_id)

    if not expired:
        return

    placeholders = ",".join("?" for _ in expired)
    await bot.db.execute(
        f"DELETE FROM raid_party_invites WHERE party_id IN ({placeholders})", expired
    )
    await bot.db.execute(
        f"DELETE FROM raid_parties WHERE id IN ({placeholders})", expired
    )
    await commit_if_needed()


async def cleanup_expired_raid_invites():
    """Удаляет приглашения, чьи кнопки уже неактуальны после таймаута."""
    cutoff = datetime.datetime.now() - datetime.timedelta(seconds=RAID_INVITE_TIMEOUT)
    async with bot.db.execute(
        "SELECT id, created_at FROM raid_party_invites"
    ) as c:
        rows = await c.fetchall()

    expired = []
    for invite_id, created_at in rows:
        created = _parse_db_time(created_at)
        if not created or created < cutoff:
            expired.append(invite_id)
    if not expired:
        return

    placeholders = ",".join("?" for _ in expired)
    await bot.db.execute(
        f"DELETE FROM raid_party_invites WHERE id IN ({placeholders})", expired
    )
    await commit_if_needed()


async def get_raid_party(user_id: int):
    """Возвращает активный отряд игрока или None."""
    await cleanup_expired_raid_parties()
    async with bot.db.execute(
        "SELECT id, leader_id, member2_id, member3_id, created_at, updated_at "
        "FROM raid_parties "
        "WHERE leader_id = ? OR member2_id = ? OR member3_id = ? "
        "ORDER BY id DESC LIMIT 1",
        (user_id, user_id, user_id),
    ) as c:
        return await c.fetchone()


async def get_raid_party_by_id(party_id: int):
    async with bot.db.execute(
        "SELECT id, leader_id, member2_id, member3_id, created_at, updated_at "
        "FROM raid_parties WHERE id = ?",
        (party_id,),
    ) as c:
        return await c.fetchone()


async def touch_raid_party(party_id: int):
    await bot.db.execute(
        "UPDATE raid_parties SET updated_at = ? WHERE id = ?",
        (datetime.datetime.now().isoformat(), party_id),
    )


async def create_raid_party(user_id: int) -> int:
    """Создаёт отряд. Игрок может быть только в одном отряде."""
    async with db_transaction():
        async with bot.db.execute(
            "SELECT id FROM raid_parties "
            "WHERE leader_id = ? OR member2_id = ? OR member3_id = ?",
            (user_id, user_id, user_id),
        ) as c:
            if await c.fetchone():
                raise ValueError("Ты уже состоишь в отряде.")

        cur = await bot.db.execute(
            "INSERT INTO raid_parties (leader_id, updated_at) VALUES (?, ?)",
            (user_id, datetime.datetime.now().isoformat()),
        )
        party_id = cur.lastrowid
        await bot.db.execute(
            "DELETE FROM raid_party_invites WHERE target_id = ?", (user_id,)
        )
    return party_id


async def join_raid_party(party_id: int, user_id: int):
    """Добавляет игрока в отряд после принятия приглашения."""
    async with db_transaction():
        async with bot.db.execute(
            "SELECT id, leader_id, member2_id, member3_id FROM raid_parties WHERE id = ?",
            (party_id,),
        ) as c:
            party = await c.fetchone()

        if not party:
            raise ValueError("Отряд уже распался.")
        members = party_member_ids(party)
        if user_id in members:
            raise ValueError("Ты уже в этом отряде.")
        if len(members) >= RAID_PARTY_MAX:
            raise ValueError("Отряд уже укомплектован.")

        async with bot.db.execute(
            "SELECT id FROM raid_parties "
            "WHERE (leader_id = ? OR member2_id = ? OR member3_id = ?) AND id != ?",
            (user_id, user_id, user_id, party_id),
        ) as c:
            if await c.fetchone():
                raise ValueError("Ты уже состоишь в другом отряде.")

        if party[2] is None:
            await bot.db.execute(
                "UPDATE raid_parties SET member2_id = ?, updated_at = ? WHERE id = ?",
                (user_id, datetime.datetime.now().isoformat(), party_id),
            )
        elif party[3] is None:
            await bot.db.execute(
                "UPDATE raid_parties SET member3_id = ?, updated_at = ? WHERE id = ?",
                (user_id, datetime.datetime.now().isoformat(), party_id),
            )
        else:
            raise ValueError("В отряде нет свободного места.")

        await bot.db.execute(
            "DELETE FROM raid_party_invites WHERE target_id = ?", (user_id,)
        )
        await bot.db.execute(
            "DELETE FROM raid_party_invites WHERE party_id = ? AND target_id = ?",
            (party_id, user_id),
        )

        async with bot.db.execute(
            "SELECT id, leader_id, member2_id, member3_id "
            "FROM raid_parties WHERE id = ?",
            (party_id,),
        ) as c:
            updated = await c.fetchone()
        if updated and len(party_member_ids(updated)) >= RAID_PARTY_MAX:
            await bot.db.execute(
                "DELETE FROM raid_party_invites WHERE party_id = ?", (party_id,)
            )


async def detach_user_from_raid_party(user_id: int) -> str:
    """Убирает игрока из отряда. Не коммитит — вызывающий код решает сам."""
    async with bot.db.execute(
        "SELECT id, leader_id, member2_id, member3_id FROM raid_parties "
        "WHERE leader_id = ? OR member2_id = ? OR member3_id = ?",
        (user_id, user_id, user_id),
    ) as c:
        party = await c.fetchone()

    await bot.db.execute(
        "DELETE FROM raid_party_invites WHERE target_id = ? OR inviter_id = ?",
        (user_id, user_id),
    )
    if not party:
        return "none"

    party_id, leader_id, member2_id, member3_id = party
    now = datetime.datetime.now().isoformat()

    if leader_id == user_id:
        if member2_id:
            await bot.db.execute(
                "UPDATE raid_parties SET leader_id = ?, member2_id = ?, "
                "member3_id = NULL, updated_at = ? WHERE id = ?",
                (member2_id, member3_id, now, party_id),
            )
            return "transferred"
        await bot.db.execute(
            "DELETE FROM raid_party_invites WHERE party_id = ?", (party_id,)
        )
        await bot.db.execute("DELETE FROM raid_parties WHERE id = ?", (party_id,))
        return "disbanded"

    if member2_id == user_id:
        await bot.db.execute(
            "UPDATE raid_parties SET member2_id = ?, member3_id = NULL, "
            "updated_at = ? WHERE id = ?",
            (member3_id, now, party_id),
        )
        return "left"

    if member3_id == user_id:
        await bot.db.execute(
            "UPDATE raid_parties SET member3_id = NULL, updated_at = ? WHERE id = ?",
            (now, party_id),
        )
        return "left"

    return "none"


async def leave_raid_party(user_id: int) -> str:
    async with db_transaction():
        return await detach_user_from_raid_party(user_id)


async def get_raid_cooldown_seconds(user_id: int) -> int:
    """Сколько секунд осталось до следующего рейда игрока."""
    async with bot.db.execute(
        "SELECT last_raid_time FROM raid_cooldowns WHERE user_id = ?", (user_id,)
    ) as c:
        row = await c.fetchone()
    last_raid = _parse_db_time(row[0]) if row else None
    if not last_raid:
        return 0
    return max(0, int(3600 - (datetime.datetime.now() - last_raid).total_seconds()))


async def perform_raid(attacker_ids: list[int], target_id: int):
    """Проводит рейд. Возвращает (result, error).

    result — словарь с деталями боя, error — текст ошибки для пользователя.
    """
    members = []
    for uid in attacker_ids:
        if uid not in members:
            members.append(uid)

    if not members:
        return None, "❌ В отряде нет участников."
    if target_id in members:
        return None, "❌ Нельзя атаковать участника своего отряда."

    now = datetime.datetime.now()
    result = {
        "members": members,
        "target_id": target_id,
        "powers": {},
        "team_power": 0,
        "def_power": 0,
        "roll_atk": 0,
        "roll_def": 0,
        "success": False,
        "loot": {},
        "capped": [],
        "target_capped": False,
        "daily": {},
        "synergy_pct": int(round(RAID_GROUP_SYNERGY * 100 * (len(members) - 1))),
    }

    try:
        async with db_transaction():
            # --- Цель ---
            async with bot.db.execute(
                "SELECT coins FROM players WHERE user_id = ?", (target_id,)
            ) as c:
                target_row = await c.fetchone()
            if not target_row:
                raise ValueError("❌ Цель не найдена.")
            target_coins = max(0, target_row[0] or 0)
            today = today_str()
            async with bot.db.execute(
                "SELECT COALESCE(SUM(amount), 0) FROM raid_loot_log "
                "WHERE target_id = ? AND date = ?",
                (target_id, today),
            ) as c:
                target_lost_today = (await c.fetchone())[0] or 0

            # --- Кулдауны атакующих ---
            placeholders = ",".join("?" for _ in members)
            async with bot.db.execute(
                f"SELECT user_id, last_raid_time FROM raid_cooldowns "
                f"WHERE user_id IN ({placeholders})",
                members,
            ) as c:
                cooldown_rows = await c.fetchall()
            cooldowns = {uid: last for uid, last in cooldown_rows}

            on_cooldown = []
            for uid in members:
                last_raid = _parse_db_time(cooldowns.get(uid))
                if not last_raid:
                    continue
                remain = 3600 - (now - last_raid).total_seconds()
                if remain > 0:
                    on_cooldown.append(f"<@{uid}> (~{max(1, int(remain // 60) + 1)} мин.)")
            if on_cooldown:
                raise ValueError(
                    "❌ Кулдаун рейда: " + ", ".join(on_cooldown) + "."
                )

            # Щит цели после предыдущей атаки.
            async with bot.db.execute(
                "SELECT last_attacked_time FROM raid_cooldowns WHERE user_id = ?",
                (target_id,),
            ) as c:
                shield_row = await c.fetchone()
            last_attacked = _parse_db_time(shield_row[0]) if shield_row else None
            if last_attacked:
                shield_left = RAID_TARGET_SHIELD_HOURS * 3600 - (
                    now - last_attacked
                ).total_seconds()
                if shield_left > 0:
                    minutes = max(1, int(shield_left // 60) + 1)
                    raise ValueError(
                        f"❌ У цели действует щит ещё {minutes} мин. "
                        "Её недавно атаковали."
                    )

            # --- Мощь ---
            powers = {}
            for uid in members:
                power = await get_combat_power(uid)
                if power <= 0:
                    raise ValueError(
                        f"❌ У <@{uid}> нет генераторов на энергостанции (мощь 0)."
                    )
                powers[uid] = power

            def_power = await get_combat_power(target_id)
            if def_power <= 0:
                raise ValueError("❌ У цели нет генераторов. Атаковать нечего.")

            team_power = sum(powers.values())
            if len(members) > 1:
                team_power = int(
                    team_power * (1 + RAID_GROUP_SYNERGY * (len(members) - 1))
                )
            if def_power < team_power * RAID_MIN_TARGET_POWER_RATIO:
                raise ValueError(
                    "❌ Цель слишком слабая для твоего отряда. "
                    "Выбери противника, сопоставимого по силе."
                )

            roll_atk = random.randint(1, team_power)
            roll_def = random.randint(1, def_power)
            success = roll_atk > roll_def

            # --- Кулдауны после рейда ---
            now_iso = now.isoformat()
            for uid in members:
                await bot.db.execute(
                    "INSERT INTO raid_cooldowns (user_id, last_raid_time) "
                    "VALUES (?, ?) "
                    "ON CONFLICT(user_id) DO UPDATE SET last_raid_time = ?",
                    (uid, now_iso, now_iso),
                )
            await bot.db.execute(
                "INSERT INTO raid_cooldowns (user_id, last_attacked_time) "
                "VALUES (?, ?) "
                "ON CONFLICT(user_id) DO UPDATE SET last_attacked_time = ?",
                (target_id, now_iso, now_iso),
            )

            # --- Добыча ---
            loot = {}
            capped = []
            daily = {}
            target_capped = False
            if success and target_coins > 0:
                total_loot = 0
                target_budget = max(
                    0,
                    int(target_coins * RAID_DAILY_LOSS_CAP) - target_lost_today,
                )
                wanted_by_uid = {}
                for uid in members:
                    bonus = (
                        await get_pet_bonus(uid, "raid_loot")
                        + await get_title_bonus(uid, "raid_loot")
                    )
                    wanted_by_uid[uid] = (
                        int(target_coins * (RAID_LOOT_RATE + bonus))
                        // len(members)
                    )

                total_wanted = sum(wanted_by_uid.values())
                scale = 1.0
                if total_wanted > target_budget:
                    scale = (target_budget / total_wanted) if total_wanted else 0.0
                    target_capped = True

                for uid, base_wanted in wanted_by_uid.items():
                    wanted = int(base_wanted * scale)

                    async with bot.db.execute(
                        "SELECT COALESCE(SUM(amount), 0) FROM raid_loot_log "
                        "WHERE user_id = ? AND date = ?",
                        (uid, today),
                    ) as c:
                        used = (await c.fetchone())[0] or 0

                    async with bot.db.execute(
                        "SELECT coins FROM players WHERE user_id = ?", (uid,)
                    ) as c:
                        row = await c.fetchone()
                    my_coins = (row[0] if row else 0) or 0
                    limit = max(1000, my_coins // 2)
                    remaining = max(0, limit - used)
                    actual = min(wanted, remaining)

                    if actual < wanted:
                        capped.append(uid)
                    daily[uid] = (used, limit)
                    if actual > 0:
                        loot[uid] = actual
                        total_loot += actual

                if total_loot > 0:
                    cur = await bot.db.execute(
                        "UPDATE players SET coins = coins - ? "
                        "WHERE user_id = ? AND coins >= ?",
                        (total_loot, target_id, total_loot),
                    )
                    if cur.rowcount == 0:
                        raise ValueError(
                            "❌ Кошелёк цели изменился. Попробуй рейд ещё раз."
                        )

                    for uid, amount in loot.items():
                        await bot.db.execute(
                            "UPDATE players SET coins = coins + ?, "
                            "total_coins_earned = total_coins_earned + ? "
                            "WHERE user_id = ?",
                            (amount, amount, uid),
                        )
                        await bot.db.execute(
                            "INSERT INTO raid_loot_log "
                            "(user_id, target_id, amount, date) VALUES (?, ?, ?, ?)",
                            (uid, target_id, amount, today),
                        )

            result.update({
                "powers": powers,
                "team_power": team_power,
                "def_power": def_power,
                "roll_atk": roll_atk,
                "roll_def": roll_def,
                "success": success,
                "loot": loot,
                "capped": capped,
                "target_capped": target_capped,
                "daily": daily,
            })
    except ValueError as e:
        return None, str(e)

    return result, None


async def finalize_raid(result: dict):
    """Обновляет квесты, победы и достижения всех участников рейда."""
    for uid in result["members"]:
        try:
            await update_quest_progress(uid, "raid_1")

            clan = await get_clan(uid)
            if clan:
                await update_clan_quest(clan[0], "raid", 1)

            if result["success"]:
                await update_story_quests(uid, "raid_win", 1)
                await bot.db.execute(
                    "UPDATE players SET raid_wins = raid_wins + 1 WHERE user_id = ?",
                    (uid,),
                )
                await commit_if_needed()
                await check_achievements(uid)
            await add_season_xp(
                uid,
                season_xp_amount(
                    "raid_win" if result["success"] else "raid_loss"
                ),
                action="raid_win" if result["success"] else "raid_loss",
            )
        except Exception:
            log.exception("Не удалось обновить прогресс рейда для %s", uid)


def build_raid_result_embed(result: dict) -> discord.Embed:
    members = result["members"]
    success = result["success"]
    lines = []

    if len(members) > 1:
        lines.append("**Отряд:** " + ", ".join(f"<@{uid}>" for uid in members))
        synergy = result["synergy_pct"]
        lines.append(
            f"Мощь отряда: **{result['team_power']}** (синергия +{synergy}%)"
        )
    else:
        lines.append(f"Твоя мощь: **{result['team_power']}**")

    lines.append(
        f"Цель: <@{result['target_id']}> · защита **{result['def_power']}**"
    )
    lines.append(
        f"Бросок атаки: **{result['roll_atk']}** · "
        f"бросок защиты: **{result['roll_def']}**"
    )

    if success:
        if result["loot"]:
            lines.append("\n🏆 **Успешный рейд!**")
            for uid, amount in result["loot"].items():
                lines.append(f"<@{uid}>: 🪙 **{amount}**")
            if result["capped"]:
                lines.append(
                    "⏳ Дневной лимит срезал добычу: "
                    + ", ".join(f"<@{uid}>" for uid in result["capped"])
                )
            if result.get("target_capped"):
                lines.append(
                    "🛡 Дневной лимит потерь цели ограничил добычу."
                )
        else:
            lines.append(
                "\n🏆 Победа, но украсть нечего: "
                "пустой кошелёк или исчерпан дневной лимит."
            )
    else:
        lines.append("\n💥 **Провал!** Ничего не украдено.")

    lines.append("\n⏳ Следующий рейд будет доступен через 1 час.")
    return BotEmbed(
        title="Результат рейда",
        description="\n".join(lines),
        color=0x2ecc71 if success else 0xe74c3c,
    )


async def send_raid_result(interaction: discord.Interaction, result: dict):
    await finalize_raid(result)
    try:
        message = await interaction.followup.send(
            embed=build_raid_result_embed(result), ephemeral=False
        )
    except discord.HTTPException:
        return
    asyncio.create_task(delete_message_later(message, PUBLIC_MESSAGE_DELETE_SECONDS))


async def build_raid_party_embed(party_id: int, viewer_id: int):
    party = await get_raid_party_by_id(party_id)
    if not party:
        return None

    members = party_member_ids(party)
    powers = {}
    for uid in members:
        powers[uid] = await get_combat_power(uid)

    lines = []
    for uid in members:
        crown = "👑 " if uid == party[1] else ""
        cooldown = await get_raid_cooldown_seconds(uid)
        status = f"⏳ ~{max(1, cooldown // 60 + 1)} мин." if cooldown else "✅ готов"
        lines.append(f"{crown}<@{uid}> — {powers[uid]} мощи · {status}")

    total_power = sum(powers.values())
    if len(members) > 1:
        total_power = int(
            total_power * (1 + RAID_GROUP_SYNERGY * (len(members) - 1))
        )

    async with bot.db.execute(
        "SELECT COUNT(*) FROM raid_party_invites WHERE party_id = ?", (party_id,)
    ) as c:
        pending_invites = (await c.fetchone())[0] or 0

    is_leader = party[1] == viewer_id
    embed = BotEmbed(
        title=f"{get_emoji('_coop')} Отряд",
        description=(
            "Ты лидер отряда. Приглашай игроков и начинай рейд."
            if is_leader
            else "Ты участник отряда. Лидер приглашает игроков и начинает рейд."
        ),
        color=0xe74c3c,
    )
    embed.add_field(name="Состав", value="\n".join(lines), inline=False)

    power_text = f"**{total_power}**"
    if len(members) > 1:
        synergy = int(round(RAID_GROUP_SYNERGY * 100 * (len(members) - 1)))
        power_text += f"\nСинергия: +{synergy}%"
    embed.add_field(
        name="Мощь отряда", value=power_text, inline=False
    )
    embed.add_field(
        name="Свободные места",
        value=f"{RAID_PARTY_MAX - len(members)} из {RAID_PARTY_MAX}",
        inline=True,
    )
    embed.add_field(
        name="Приглашения",
        value=str(pending_invites),
        inline=True,
    )
    embed.set_footer(
        text=f"Отряд распадается после {RAID_PARTY_TTL_MINUTES} минут бездействия."
    )
    return embed


async def open_raid_menu(interaction: discord.Interaction, author_id: int):
    embed = BotEmbed(
        title=f"{get_emoji('_raid')} Подготовка к рейду",
        description=(
            "Атакуй чужую энергостанцию и забери часть монет.\n\n"
            "**В одиночку** — только твоя мощь.\n"
            "**Собрать отряд** — до 3 игроков, общая мощь и синергия.\n"
            "Базовая добыча делится поровну, бонусы применяются к доле каждого."
        ),
        color=0xe74c3c,
    )
    await interaction.edit_original_response(embed=embed, view=RaidMenuView(author_id))


async def open_raid_party(interaction: discord.Interaction, author_id: int, create: bool = False):
    party = await get_raid_party(author_id)
    if not party and create:
        try:
            party_id = await create_raid_party(author_id)
        except ValueError as e:
            embed = BotEmbed(
                title=f"{get_emoji('_raid')} Подготовка к рейду",
                description=f"❌ {e}",
                color=0xe74c3c,
            )
            return await interaction.edit_original_response(
                embed=embed, view=RaidMenuView(author_id)
            )
        party = await get_raid_party_by_id(party_id)

    if not party:
        embed = BotEmbed(
            title=f"{get_emoji('_coop')} Отряд",
            description="Отряд не найден. Создай новый.",
            color=0xe74c3c,
        )
        return await interaction.edit_original_response(
            embed=embed, view=RaidMenuView(author_id)
        )

    await touch_raid_party(party[0])
    await commit_if_needed()

    embed = await build_raid_party_embed(party[0], author_id)
    if embed is None:
        embed = BotEmbed(
            title=f"{get_emoji('_coop')} Отряд",
            description="Отряд уже распался.",
            color=0xe74c3c,
        )
        return await interaction.edit_original_response(
            embed=embed, view=RaidMenuView(author_id)
        )

    await interaction.edit_original_response(
        embed=embed, view=RaidPartyView(author_id, party[0])
    )


