class CoinsToGemsModal(discord.ui.Modal, title="Обмен монет на гемы"):
    amount = discord.ui.TextInput(
        label=f"Сколько монет обменять (мин. {COIN_EXCHANGE_MIN})",
        placeholder=f"Например, {COINS_PER_GEM}",
        required=True
    )

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        user_id = interaction.user.id

        try:
            coins = int(self.amount.value)
            if coins < COIN_EXCHANGE_MIN:
                raise ValueError
        except ValueError:
            await interaction.followup.send(
                f"❌ Минимум {COIN_EXCHANGE_MIN} монет.", ephemeral=True
            )
            return

        gems_gross = coins // COINS_PER_GEM
        if gems_gross < 1:
            await interaction.followup.send(
                f"❌ Нужно минимум {COINS_PER_GEM} монет для 1 гема.", ephemeral=True
            )
            return

        fee_rate = exchange_fee_rate(coins, "coins_to_gems")
        fee_gems = int(gems_gross * fee_rate)
        gems = gems_gross - fee_gems
        if gems < 1:
            await interaction.followup.send(
                "❌ Комиссия съедает всю сумму. Обменяй больше монет.",
                ephemeral=True,
            )
            return

        spent_coins = gems_gross * COINS_PER_GEM
        remainder = coins - spent_coins  # сколько не обменялось

        # атомарное списание (один раз!)
        cursor = await bot.db.execute(
            "UPDATE players SET coins = coins - ?, gems = gems + ? "
            "WHERE user_id = ? AND coins >= ?",
            (spent_coins, gems, user_id, spent_coins)
        )
        if cursor.rowcount == 0:
            await interaction.followup.send(
                f"❌ Не хватает монет (нужно 🪙 {spent_coins}).", ephemeral=True
            )
            return
        await commit_if_needed()

        msg = (
            f"✅ Обменяно 🪙 {spent_coins} → 💎 {gems}.\n"
            f"Комиссия: **{int(fee_rate * 100)}%** (💎 {fee_gems})."
        )
        if remainder > 0:
            msg += f"\n⚠️ Остаток 🪙 {remainder} не обменян (нужно кратно {COINS_PER_GEM})."
        await interaction.followup.send(msg, ephemeral=True)


class GemsToCoinsModal(discord.ui.Modal, title="Обмен гемов на монеты"):
    amount = discord.ui.TextInput(
        label=f"Сколько гемов обменять (мин. {GEM_EXCHANGE_MIN})",
        placeholder="Например, 1",
        required=True
    )

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        user_id = interaction.user.id
        try:
            gems = int(self.amount.value)
            if gems < GEM_EXCHANGE_MIN:
                raise ValueError
        except ValueError:
            await interaction.followup.send(f"❌ Минимум {GEM_EXCHANGE_MIN} гем.", ephemeral=True)
            return

        coins_gross = gems * GEMS_PER_COIN_RATE
        fee_rate = exchange_fee_rate(gems, "gems_to_coins")
        fee_coins = int(coins_gross * fee_rate)
        coins = coins_gross - fee_coins

        # атомарное списание: обновится только если gems >= нужного
        cursor = await bot.db.execute(
            "UPDATE players SET gems = gems - ?, coins = coins + ? "
            "WHERE user_id = ? AND gems >= ?",
            (gems, coins, user_id, gems)
        )
        if cursor.rowcount == 0:
            # не хватило гемов (или race condition)
            async with bot.db.execute(
                "SELECT gems FROM players WHERE user_id = ?", (user_id,)
            ) as c:
                row = await c.fetchone()
            balance = row[0] if row else 0
            await interaction.followup.send(
                f"❌ Нужно 💎 {gems}, у тебя {balance}.", ephemeral=True
            )
            return
        await commit_if_needed()

        await interaction.followup.send(
            f"✅ Обменяно 💎 {gems} → 🪙 {coins}.\n"
            f"Комиссия: **{int(fee_rate * 100)}%** (🪙 {fee_coins}).",
            ephemeral=True,
        )


