async def open_sell_view(interaction: discord.Interaction, author_id: int, page: int = 0):
    user_id = interaction.user.id
    guild_id = interaction.guild_id
    settings = await get_settings(guild_id)
    custom = settings["custom_emojis"]

    async with bot.db.execute("""
        SELECT inv.slot, inv.item_id, i.name, i.emoji, i.price, inv.stars, i.rarity
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = 'storage'
              AND COALESCE(inv.is_locked, 0) = 0
        ORDER BY inv.slot ASC
    """, (user_id,)) as c:
        rows = await c.fetchall()

    rows = [row for row in rows if row[6] in SELL_ALLOWED_RARITIES]

    if not rows:
        await interaction.followup.send(
            "❌ В хранилище нет предметов, которые можно продать.",
            ephemeral=True,
        )
        return

    total_pages = max(1, (len(rows) + SHOP_SELECT_PAGE_SIZE - 1) // SHOP_SELECT_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page * SHOP_SELECT_PAGE_SIZE: page * SHOP_SELECT_PAGE_SIZE + SHOP_SELECT_PAGE_SIZE]

    options = []
    for slot, item_id, name, default_emoji, price, stars, rarity in chunk:
        emoji_obj = parse_emoji_safe(custom.get(item_id, default_emoji))
        sell_price = calculate_sell_price(price, stars)
        stars_str = f" {stars}★" if stars > 0 else ""
        options.append(discord.SelectOption(
            label=f"Слот {slot}: {name}{stars_str} — 🪙 {sell_price}"[:100],
            value=f"{slot}:{item_id}:{stars}",
            emoji=emoji_obj,
        ))

    embed = BotEmbed(
        title=f"{get_emoji('_sell')} Продажа предметов",
        description=(
            f"Страница {page + 1}/{total_pages}\n"
            f"Цена продажи — {int(SELL_RATE * 100)}% от магазинной."
        ),
        color=0x2ecc71,
    )
    await interaction.edit_original_response(
        embed=embed,
        view=SellSelectView(author_id, options, page, total_pages),
    )


class SellSelectView(SafeView):
    feature_key = "storage"
    def __init__(self, author_id: int, options: list[discord.SelectOption], page: int, total_pages: int):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.page = page
        self.total_pages = total_pages
        self.add_item(make_select("Выбери предмет", options, self.item_select, row=0))

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            nxt.callback = self.next_page
            self.add_item(nxt)

        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.danger, row=2)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    async def item_select(self, interaction: discord.Interaction):
        value = interaction.data["values"][0]
        parts = value.split(":", 2)
        slot = int(parts[0])
        item_id = parts[1]
        stars = int(parts[2]) if len(parts) > 2 else 0
        await interaction.response.defer()

        async with bot.db.execute(
            "SELECT i.name, i.price, inv.stars, i.rarity FROM inventory inv "
            "JOIN items i ON inv.item_id = i.id "
            "WHERE inv.user_id = ? AND inv.location = 'storage' "
            "AND COALESCE(inv.is_locked, 0) = 0 "
            "AND inv.slot = ? AND inv.item_id = ? AND inv.stars = ?",
            (interaction.user.id, slot, item_id, stars)
        ) as c:
            row = await c.fetchone()
        if not row:
            await interaction.followup.send("❌ Предмет не найден.", ephemeral=True)
            return

        name, price, stars, rarity = row
        if rarity not in SELL_ALLOWED_RARITIES:
            await interaction.followup.send(
                f"❌ Предметы редкости **{RARITY_NAMES.get(rarity, rarity)}** не продаются. "
                f"Используй синтез или аукцион.",
                ephemeral=True
            )
            return

        sell_price = calculate_sell_price(price, stars)

        embed = BotEmbed(
            title=f"{get_emoji('_sell')} Подтверждение продажи",
            description=(
                f"**{name}** {'⭐' * stars if stars > 0 else ''}\n"
                f"Редкость: {RARITY_NAMES.get(rarity, rarity)}\n"
                f"Цена продажи: 🪙 {sell_price} "
                f"({int(SELL_RATE*100)}% от магазина + бонус звёзд)\n\n"
                f"Продать этот предмет?"
            ),
            color=0x2ecc71
        )
        await interaction.edit_original_response(
            embed=embed,
            view=SellConfirmView(
                self.author_id, slot, item_id, stars, sell_price, self.page
            )
        )

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_sell_view(interaction, self.author_id, self.page - 1)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_sell_view(interaction, self.author_id, self.page + 1)

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = await build_storage_embed(interaction)
        await interaction.edit_original_response(
            embed=embed, view=StorageView(self.author_id, return_to="profile")
        )

class SellConfirmView(SafeView):
    feature_key = "storage"
    def __init__(
        self,
        author_id: int,
        slot: int,
        item_id: str,
        stars: int,
        price: int,
        page: int,
    ):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.slot = slot
        self.item_id = item_id
        self.stars = stars
        self.price = price  # уже посчитанная цена продажи
        self.page = page

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    @discord.ui.button(label="Продать", emoji=get_emoji("_sell"), style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        user_id = interaction.user.id

        try:
            async with db_transaction():
                # повторная проверка: предмет ещё есть, редкость разрешена
                async with bot.db.execute(
                    "SELECT i.price, i.rarity, inv.stars FROM inventory inv "
                    "JOIN items i ON inv.item_id = i.id "
                    "WHERE inv.user_id = ? AND inv.location = 'storage' "
                    "AND COALESCE(inv.is_locked, 0) = 0 "
                    "AND inv.slot = ? AND inv.item_id = ? AND inv.stars = ?",
                    (user_id, self.slot, self.item_id, self.stars),
                ) as c:
                    row = await c.fetchone()

                if not row:
                    raise ValueError("Предмета уже нет.")

                price, rarity, stars = row
                if rarity not in SELL_ALLOWED_RARITIES:
                    raise ValueError(
                        f"Предметы редкости **{RARITY_NAMES.get(rarity, rarity)}** не продаются."
                    )

                sell_price = calculate_sell_price(price, stars)

                cursor = await bot.db.execute(
                    "DELETE FROM inventory "
                    "WHERE user_id = ? AND location = 'storage' AND slot = ? "
                    "AND item_id = ? AND stars = ? AND COALESCE(is_locked, 0) = 0",
                    (user_id, self.slot, self.item_id, self.stars),
                )
                if cursor.rowcount == 0:
                    raise ValueError("Предмета уже нет.")

                await bot.db.execute(
                    "UPDATE players SET coins = coins + ? WHERE user_id = ?",
                    (sell_price, user_id),
                )
        except ValueError as e:
            await interaction.edit_original_response(
                embed=BotEmbed(title="❌ Нельзя продать", description=str(e), color=0xe74c3c),
                view=StorageView(self.author_id, return_to="profile"),
            )
            return

        await update_quest_progress(user_id, "sell_3")
        await check_achievements(user_id)

        embed = BotEmbed(
            title=f"{get_emoji('_sell')} Продано",
            description=f"Ты получил 🪙 **{sell_price}** за предмет ({int(SELL_RATE*100)}% от магазина).",
            color=0x2ecc71
        )
        await interaction.edit_original_response(
            embed=embed, view=StorageView(self.author_id, return_to="profile")
        )

    @discord.ui.button(label="Отмена", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        embed = await build_storage_embed(interaction)
        await interaction.edit_original_response(
            embed=embed, view=StorageView(self.author_id, return_to="profile")
        )


