async def _swap_location_size(author_id: int, location: str) -> int:
    if location == "profile":
        return await get_grid_size(author_id)
    return await get_storage_size(author_id)


def _swap_grid_preview(slots, rows_by_slot, custom) -> str:
    """Компактная графическая схема слотов для embed."""
    cells = []
    for slot in slots:
        row = rows_by_slot.get(slot)
        if row is None:
            cells.append(f"`{slot}` ·")
        else:
            item_id, _name, default_emoji, stars = row
            emoji = custom.get(item_id, default_emoji)
            cells.append(f"`{slot}` {emoji}{f' {stars}★' if stars else ''}")
    return "\n".join(
        " ".join(cells[index:index + 5])
        for index in range(0, len(cells), 5)
    )


async def _build_swap_first_page(
    location: str,
    author_id: int,
    guild_id: int,
    page: int = 0,
    main_message=None,
):
    settings = await get_settings(guild_id)
    custom = settings["custom_emojis"]

    async with bot.db.execute("""
        SELECT inv.slot, inv.item_id, i.name, i.emoji, inv.stars
        FROM inventory inv JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = ? ORDER BY inv.slot ASC
    """, (author_id, location)) as c:
        rows = await c.fetchall()

    if not rows:
        return None, None, "❌ На энергостанции нет предметов для перемещения."

    page_size = SHOP_SELECT_PAGE_SIZE
    total_pages = max(1, (len(rows) + page_size - 1) // page_size)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page * page_size:page * page_size + page_size]

    options = []
    for slot, item_id, name, default_emoji, stars in chunk:
        emoji_obj = parse_emoji_safe(custom.get(item_id, default_emoji))
        stars_str = f" {stars}★" if stars > 0 else ""
        short_name = name[:40] + "..." if len(name) > 40 else name
        options.append(discord.SelectOption(
            label=f"Слот {slot}: {short_name}{stars_str}",
            value=f"{slot}:{item_id}:{stars}",
            emoji=emoji_obj
        ))

    embed = BotEmbed(
        title="↔️ Обмен местами",
        description=(
            f"Шаг 1: Выбери предмет, который хочешь **переместить** на другой слот.\n"
            f"Страница {page + 1}/{total_pages}"
        ),
        color=0x3498db
    )
    by_slot = {row[0]: row[1:] for row in rows}
    embed.add_field(
        name="Схема слотов",
        value=_swap_grid_preview(
            [row[0] for row in chunk], by_slot, custom
        ),
        inline=False,
    )
    view = SwapFirstView(
        author_id, location, options, page, total_pages, main_message
    )
    return embed, view, None


async def _build_swap_second_page(
    location: str,
    author_id: int,
    first_slot: int,
    guild_id: int,
    page: int = 0,
    main_message=None,
):
    settings = await get_settings(guild_id)
    custom = settings["custom_emojis"]

    async with bot.db.execute("""
        SELECT inv.slot, inv.item_id, i.name, i.emoji, inv.stars
        FROM inventory inv JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = ?
        ORDER BY inv.slot ASC
    """, (author_id, location)) as c:
        rows = await c.fetchall()
    row_by_slot = {row[0]: row[1:] for row in rows}
    size = await _swap_location_size(author_id, location)
    slots = [slot for slot in range(size) if slot != first_slot]
    if not slots:
        return None, None, "❌ Нет других слотов для обмена."

    page_size = SHOP_SELECT_PAGE_SIZE
    total_pages = max(1, (len(slots) + page_size - 1) // page_size)
    page = max(0, min(page, total_pages - 1))
    chunk = slots[page * page_size:page * page_size + page_size]
    empty_emoji = parse_emoji_safe(get_emoji("_inventory"))

    options = []
    for slot in chunk:
        row = row_by_slot.get(slot)
        if row is None:
            options.append(discord.SelectOption(
                label=f"Слот {slot}: пусто",
                value=str(slot),
                emoji=empty_emoji,
            ))
            continue
        item_id2, name, default_emoji, stars2 = row
        emoji_obj = parse_emoji_safe(custom.get(item_id2, default_emoji))
        stars_str = f" {stars2}★" if stars2 > 0 else ""
        short_name = name[:40] + "..." if len(name) > 40 else name
        options.append(discord.SelectOption(
            label=f"Слот {slot}: {short_name}{stars_str}",
            value=str(slot),
            emoji=emoji_obj
        ))

    embed = BotEmbed(
        title="↔️ Обмен местами",
        description=(
            f"Шаг 2: Выбран предмет из **слота {first_slot}**.\n"
            "Выбери занятый слот для обмена или пустой для перемещения.\n"
            f"Страница {page + 1}/{total_pages}"
        ),
        color=0x3498db
    )
    embed.add_field(
        name="Схема слотов",
        value=_swap_grid_preview(chunk, row_by_slot, custom),
        inline=False,
    )
    view = SwapSecondView(
        author_id, location, first_slot, options, page, total_pages, main_message
    )
    return embed, view, None


async def open_swap_view(interaction: discord.Interaction, location: str, author_id: int):
    embed, view, error = await _build_swap_first_page(
        location, author_id, interaction.guild_id, 0, interaction.message
    )
    if error:
        return await interaction.followup.send(error, ephemeral=True)
    await interaction.followup.send(embed=embed, view=view, ephemeral=True)


class SwapFirstView(SafeView):
    feature_key = "storage"
    def __init__(
        self,
        author_id: int,
        location: str,
        options: list[discord.SelectOption],
        page: int = 0,
        total_pages: int = 1,
        main_message=None,
    ):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.location = location
        self.feature_key = "storage" if location == "storage" else None
        self.page = page
        self.total_pages = total_pages
        self.main_message = main_message
        self.add_item(make_select("Выбери предмет", options, self.first_select, row=0))

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            nxt.callback = self.next_page
            self.add_item(nxt)

        close = discord.ui.Button(label="Закрыть", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.danger, row=2)
        close.callback = self.close_window
        self.add_item(close)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    async def first_select(self, interaction: discord.Interaction):
        first_slot = int(interaction.data["values"][0].split(":", 1)[0])
        await interaction.response.defer()

        embed, view, error = await _build_swap_second_page(
            self.location,
            self.author_id,
            first_slot,
            interaction.guild_id,
            0,
            self.main_message,
        )
        if error:
            return await interaction.followup.send(error, ephemeral=True)
        await interaction.edit_original_response(embed=embed, view=view)

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed, view, error = await _build_swap_first_page(
            self.location, self.author_id, interaction.guild_id,
            self.page - 1, self.main_message,
        )
        if error:
            return await interaction.followup.send(error, ephemeral=True)
        await interaction.edit_original_response(embed=embed, view=view)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed, view, error = await _build_swap_first_page(
            self.location, self.author_id, interaction.guild_id,
            self.page + 1, self.main_message,
        )
        if error:
            return await interaction.followup.send(error, ephemeral=True)
        await interaction.edit_original_response(embed=embed, view=view)

    async def close_window(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await interaction.delete_original_response()


class SwapSecondView(SafeView):
    feature_key = "storage"
    def __init__(
        self,
        author_id: int,
        location: str,
        first_slot: int,
        options: list[discord.SelectOption],
        page: int = 0,
        total_pages: int = 1,
        main_message=None,
    ):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.location = location
        self.feature_key = "storage" if location == "storage" else None
        self.first_slot = first_slot
        self.page = page
        self.total_pages = total_pages
        self.main_message = main_message
        self.add_item(make_select("Выбери слот для обмена", options, self.second_select, row=0))

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            nxt.callback = self.next_page
            self.add_item(nxt)

        close = discord.ui.Button(label="Отмена", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.danger, row=2)
        close.callback = self.close_window
        self.add_item(close)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await self.check_owner(interaction)

    async def second_select(self, interaction: discord.Interaction):
        second_slot = int(interaction.data["values"][0])
        await interaction.response.defer()

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT item_id, stars, COALESCE(is_locked, 0) FROM inventory "
                    "WHERE user_id = ? AND location = ? AND slot = ?",
                    (self.author_id, self.location, self.first_slot)
                ) as c:
                    first = await c.fetchone()
                async with bot.db.execute(
                    "SELECT item_id, stars, COALESCE(is_locked, 0) FROM inventory "
                    "WHERE user_id = ? AND location = ? AND slot = ?",
                    (self.author_id, self.location, second_slot)
                ) as c:
                    second = await c.fetchone()

                if not first:
                    raise ValueError("Исходный слот пуст.")

                if second is None:
                    cur = await bot.db.execute(
                        "DELETE FROM inventory "
                        "WHERE user_id = ? AND location = ? AND slot = ?",
                        (self.author_id, self.location, self.first_slot)
                    )
                    if cur.rowcount == 0:
                        raise ValueError("Предмет уже перемещён.")
                    await bot.db.execute(
                        "INSERT INTO inventory "
                        "(user_id, slot, item_id, location, stars, is_locked) "
                        "VALUES (?, ?, ?, ?, ?, ?)",
                        (
                            self.author_id,
                            second_slot,
                            first[0],
                            self.location,
                            first[1],
                            first[2],
                        )
                    )
                    result_title = "✅ Предмет перемещён"
                    result_text = (
                        f"Предмет из слота **{self.first_slot}** перемещён "
                        f"в пустой слот **{second_slot}**."
                    )
                else:
                    cur = await bot.db.execute(
                        "DELETE FROM inventory "
                        "WHERE user_id = ? AND location = ? "
                        "AND slot IN (?, ?)",
                        (
                            self.author_id,
                            self.location,
                            self.first_slot,
                            second_slot,
                        )
                    )
                    if cur.rowcount < 2:
                        raise ValueError("Один из слотов уже изменился.")
                    await bot.db.execute(
                        "INSERT INTO inventory "
                        "(user_id, slot, item_id, location, stars, is_locked) "
                        "VALUES (?, ?, ?, ?, ?, ?)",
                        (
                            self.author_id,
                            self.first_slot,
                            second[0],
                            self.location,
                            second[1],
                            second[2],
                        )
                    )
                    await bot.db.execute(
                        "INSERT INTO inventory "
                        "(user_id, slot, item_id, location, stars, is_locked) "
                        "VALUES (?, ?, ?, ?, ?, ?)",
                        (
                            self.author_id,
                            second_slot,
                            first[0],
                            self.location,
                            first[1],
                            first[2],
                        )
                    )
                    result_title = "✅ Слоты поменяны"
                    result_text = (
                        f"Предметы в слотах **{self.first_slot}** и "
                        f"**{second_slot}** поменялись местами."
                    )
        except (ValueError, aiosqlite.IntegrityError) as exc:
            return await interaction.edit_original_response(
                embed=BotEmbed(
                    title="❌ Ошибка",
                    description=str(exc),
                    color=0xe74c3c,
                ),
                view=None,
            )
        await update_quest_progress(self.author_id, "swap_1")

        embed = BotEmbed(
            title=result_title,
            description=result_text,
            color=0x2ecc71
        )
        await interaction.edit_original_response(embed=embed, view=None)

        if self.main_message:
            if self.location == "profile":
                main_embed = await build_profile_embed(interaction)
                main_view = ProfileView(self.author_id)
            else:
                main_embed = await build_storage_embed(interaction)
                main_view = StorageView(self.author_id)
            try:
                await self.main_message.edit(embed=main_embed, view=main_view)
            except discord.HTTPException:
                pass

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed, view, error = await _build_swap_second_page(
            self.location, self.author_id, self.first_slot,
            interaction.guild_id, self.page - 1, self.main_message,
        )
        if error:
            return await interaction.followup.send(error, ephemeral=True)
        await interaction.edit_original_response(embed=embed, view=view)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed, view, error = await _build_swap_second_page(
            self.location, self.author_id, self.first_slot,
            interaction.guild_id, self.page + 1, self.main_message,
        )
        if error:
            return await interaction.followup.send(error, ephemeral=True)
        await interaction.edit_original_response(embed=embed, view=view)

    async def close_window(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await interaction.delete_original_response()


