#  ⭐ УЛУЧШЕНИЕ ЗВЁЗД
# ============================================================

async def get_star_pity(user_id: int, item_id: str, target_star: int) -> int:
    async with bot.db.execute(
        "SELECT failures FROM star_pity "
        "WHERE user_id = ? AND item_id = ? AND target_star = ?",
        (user_id, item_id, target_star),
    ) as c:
        row = await c.fetchone()
    return (row[0] if row else 0) or 0


async def get_star_chance(user_id: int, item_id: str, target_star: int) -> tuple[float, int, bool]:
    settings = STAR_UPGRADE.get(target_star, {"chance": 1.0})
    pity = await get_star_pity(user_id, item_id, target_star)
    pity_bonus = min(STAR_PITY_MAX, pity * STAR_PITY_BONUS)
    final_chance = min(1.0, settings["chance"] + pity_bonus)
    guaranteed = pity >= STAR_HARD_PITY - 1
    if guaranteed:
        final_chance = 1.0
    return final_chance, pity, guaranteed


async def open_star_view(
    interaction: discord.Interaction,
    author_id: int,
    page: int = 0,
):
    user_id = interaction.user.id
    guild_id = interaction.guild_id
    settings = await get_settings(guild_id)
    custom = settings["custom_emojis"]

    async with bot.db.execute("""
        SELECT inv.location, inv.slot, inv.item_id, i.name, i.emoji, inv.stars
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location IN ('profile', 'storage')
              AND inv.stars < 5
        ORDER BY CASE inv.location WHEN 'profile' THEN 0 ELSE 1 END,
                 inv.slot ASC
    """, (user_id,)) as c:
        rows = await c.fetchall()

    if not rows:
        await interaction.followup.send("❌ Нет генераторов для улучшения (все 5★ или пусто).", ephemeral=True)
        return

    page_size = 25
    total_pages = max(1, (len(rows) + page_size - 1) // page_size)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page * page_size:(page + 1) * page_size]

    options = []
    for location, slot, item_id, name, default_emoji, stars in chunk:
        emoji_str = custom.get(item_id, default_emoji)
        emoji_obj = parse_emoji_safe(emoji_str)
        next_star = stars + 1
        need = STAR_UPGRADE[next_star]["copies"]
        async with bot.db.execute(
            "SELECT COUNT(*) FROM inventory WHERE user_id = ? "
            "AND location IN ('profile', 'storage') "
            "AND item_id = ? AND stars = ?",
            (user_id, item_id, stars)
        ) as c:
            have = (await c.fetchone())[0]
        location_label = "Энергостанция" if location == "profile" else "Хранилище"
        options.append(discord.SelectOption(
            label=(
                f"{location_label} · слот {slot}: {name} "
                f"{stars}★ → {next_star}★ ({have}/{need})"
            )[:100],
            value=f"{location}:{slot}:{item_id}:{stars}",
            emoji=emoji_obj
        ))

    embed = BotEmbed(
        title="⭐ Улучшение звёзд",
        description=(
            f"Страница {page + 1}/{total_pages}\n"
            f"Бонус к доходу за звёзды (суммарный):\n"
            f"1★ +{int(STAR_BONUS[1] * 100)}%, 2★ +{int(STAR_BONUS[2] * 100)}%, "
            f"3★ +{int(STAR_BONUS[3] * 100)}%, 4★ +{int(STAR_BONUS[4] * 100)}%, "
            f"5★ +{int(STAR_BONUS[5] * 100)}%.\n\n"
            f"Чтобы поднять звезду, нужно **несколько копий** того же генератора с такой же звёздностью.\n"
            f"При провале сгорает одна копия, но звезда **не понижается**.\n\n"
            f"Выбери генератор на энергостанции или хранилище:"
        ),
        color=0xf1c40f
    )
    await interaction.edit_original_response(
        embed=embed,
        view=StarSelectView(author_id, options, page, total_pages),
    )


class StarSelectView(SafeView):
    feature_key = "stars"
    def __init__(
        self,
        author_id: int,
        options: list[discord.SelectOption],
        page: int = 0,
        total_pages: int = 1,
    ):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.page = page
        self.total_pages = total_pages
        self.add_item(make_select("Выбери генератор", options, self.item_select, row=0))
        if total_pages > 1:
            prev = discord.ui.Button(
                label="Стр.", emoji=get_emoji("_back"),
                style=discord.ButtonStyle.secondary, row=1,
                disabled=page <= 0,
            )
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(
                label="Стр.", emoji=get_emoji("_forward"),
                style=discord.ButtonStyle.secondary, row=1,
                disabled=page >= total_pages - 1,
            )
            nxt.callback = self.next_page
            self.add_item(nxt)
        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=2)
        back.callback = self.back
        self.add_item(back)

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_star_view(interaction, self.author_id, self.page - 1)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_star_view(interaction, self.author_id, self.page + 1)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    async def item_select(self, interaction: discord.Interaction):
        value = interaction.data["values"][0]
        
        # Парсинг: "location:slot:item_id:stars" (старый формат — без location).
        parts = value.split(":")
        if len(parts) >= 4:
            location, slot_str, item_id, stars_str = parts[:4]
        else:
            location = "profile"
            slot_str, item_id, stars_str = parts[:3]
        slot = int(slot_str)
        stars = int(stars_str) if stars_str else 0
        
        next_star = stars + 1
        if next_star > 5:
            await interaction.response.defer()
            await interaction.followup.send("❌ Уже 5★.", ephemeral=True)
            return
            
        await interaction.response.defer()
        await show_star_confirm(
            interaction,
            slot,
            item_id,
            stars,
            next_star,
            self.author_id,
            location=location,
        )

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await go_back(interaction, self.author_id, fallback="profile")


async def show_star_confirm(
    interaction: discord.Interaction,
    slot: int,
    item_id: str,
    current_stars: int,
    next_star: int,
    author_id: int,
    location: str = "profile",
):
    guild_id = interaction.guild_id
    settings = await get_settings(guild_id)
    custom = settings["custom_emojis"]
    async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
        row = await c.fetchone()
    name, default_emoji = row if row else ("генератор", "⚙️")
    emoji = custom.get(item_id, default_emoji)

    settings_star = STAR_UPGRADE[next_star]
    async with bot.db.execute(
        "SELECT COUNT(*) FROM inventory WHERE user_id = ? "
        "AND location IN ('profile', 'storage') "
        "AND item_id = ? AND stars = ?",
        (interaction.user.id, item_id, current_stars)
    ) as c:
        have = (await c.fetchone())[0]

    need = settings_star["copies"]
    enough = have >= need
    final_chance, pity, guaranteed = await get_star_chance(
        interaction.user.id, item_id, next_star
    )
    chance_str = "100% (гарантия)" if guaranteed else f"{int(final_chance * 100)}%"
    pity_str = (
        f"\nPity: **{pity}/{STAR_HARD_PITY - 1}** "
        f"(+{int(min(STAR_PITY_MAX, pity * STAR_PITY_BONUS) * 100)}%)"
        if pity
        else ""
    )
    location_label = "Энергостанция" if location == "profile" else "Хранилище"

    embed = BotEmbed(
        title=f"⭐ Улучшение до {next_star}★",
        description=(
            f"Генератор: {emoji} **{name}** "
            f"({location_label}, слот {slot}, {current_stars}★)\n\n"
            f"Нужно копий: **{have}/{need}** (энергостанция + хранилище)\n"
            f"Шанс успеха: **{chance_str}**{pity_str}\n"
            f"Стоимость: **💎 {settings_star['gems']}**\n"
            f"Новый суммарный бонус: **+{int(STAR_BONUS[next_star] * 100)}%** к доходу.\n\n"
            f"При провале сгорает одна копия, но звезда **не понижается**."
        ),
        color=0xf1c40f if enough else 0xe74c3c
    )
    await interaction.edit_original_response(
        embed=embed,
        view=StarConfirmView(
            author_id,
            slot,
            item_id,
            current_stars,
            next_star,
            location=location,
        )
    )


class StarConfirmView(SafeView):
    feature_key = "stars"
    def __init__(
        self,
        author_id: int,
        slot: int,
        item_id: str,
        current_stars: int,
        next_star: int,
        location: str = "profile",
    ):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.slot = slot
        self.item_id = item_id
        self.current_stars = current_stars
        self.next_star = next_star
        self.location = location

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Улучшить", emoji=get_emoji("_stars"), style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        user_id = interaction.user.id
        settings_star = STAR_UPGRADE[self.next_star]
        cost = settings_star["gems"]
        need = settings_star["copies"]
        final_chance, pity, guaranteed = await get_star_chance(
            user_id, self.item_id, self.next_star
        )

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT item_id, stars FROM inventory "
                    "WHERE user_id = ? AND location = ? AND slot = ?",
                    (user_id, self.location, self.slot),
                ) as c:
                    row = await c.fetchone()
                if not row:
                    raise ValueError("Генератор не найден.")
                real_item_id, real_stars = row
                if real_item_id != self.item_id or real_stars != self.current_stars:
                    raise ValueError("Данные изменились, попробуй снова.")

                async with bot.db.execute(
                    "SELECT location, slot FROM inventory "
                    "WHERE user_id = ? AND item_id = ? AND stars = ? "
                    "AND location IN ('profile', 'storage') "
                    "ORDER BY CASE location WHEN 'profile' THEN 0 ELSE 1 END, "
                    "slot ASC",
                    (user_id, self.item_id, self.current_stars),
                ) as c:
                    copies = [(r[0], r[1]) for r in await c.fetchall()]

                if len(copies) < need:
                    raise ValueError(f"Нужно {need} копий, у тебя {len(copies)}.")

                if cost > 0:
                    cur = await bot.db.execute(
                        "UPDATE players SET gems = gems - ? "
                        "WHERE user_id = ? AND gems >= ?",
                        (cost, user_id, cost),
                    )
                    if cur.rowcount == 0:
                        raise ValueError(f"Нужно 💎 {cost}.")

                selected = (self.location, self.slot)
                keep = selected if selected in copies else copies[0]
                to_delete = [copy for copy in copies if copy != keep][:need - 1]

                for copy_location, copy_slot in to_delete:
                    await bot.db.execute(
                        "DELETE FROM inventory WHERE user_id = ? "
                        "AND location = ? AND slot = ?",
                        (user_id, copy_location, copy_slot),
                    )

                success = guaranteed or random.random() < final_chance
                if success:
                    await bot.db.execute(
                        "UPDATE inventory SET stars = ? "
                        "WHERE user_id = ? AND location = ? AND slot = ?",
                        (self.next_star, user_id, keep[0], keep[1]),
                    )
                    await bot.db.execute(
                        "INSERT OR IGNORE INTO player_star_collection "
                        "(user_id, item_id, stars) VALUES (?, ?, ?)",
                        (user_id, self.item_id, self.next_star),
                    )
                    await bot.db.execute(
                        "DELETE FROM star_pity "
                        "WHERE user_id = ? AND item_id = ? AND target_star = ?",
                        (user_id, self.item_id, self.next_star),
                    )
                else:
                    await bot.db.execute("""
                        INSERT INTO star_pity
                        (user_id, item_id, target_star, failures)
                        VALUES (?, ?, ?, 1)
                        ON CONFLICT(user_id, item_id, target_star)
                        DO UPDATE SET failures = failures + 1
                    """, (user_id, self.item_id, self.next_star))
        except ValueError as e:
            return await self.fail(interaction, f"❌ {e}")

        if success:
            await update_story_quests(self.author_id, "stars", 1)
            await update_quest_progress(self.author_id, "star_up_1")
            unlocked = await check_achievements(user_id)
            location_label = "Энергостанция" if keep[0] == "profile" else "Хранилище"
            desc = (
                f"Генератор улучшен до **{self.next_star}★** "
                f"({location_label}, слот {keep[1]}).\n"
                f"Суммарный бонус к доходу: **+{int(STAR_BONUS[self.next_star] * 100)}%**.\n"
                f"Сгорело копий: **{len(to_delete)}**."
            )
            if unlocked:
                desc += "\n\n🏆 " + ", ".join(f"{e} {n}" for e, n, _ in unlocked)
            embed = BotEmbed(title="⭐ Успех!", description=desc, color=0x2ecc71)
        else:
            await update_quest_progress(self.author_id, "star_fail_1")
            embed = BotEmbed(
                title="💥 Провал",
                description=(
                    f"Улучшение до **{self.next_star}★** не удалось.\n"
                    f"Сгорело копий: **{len(to_delete)}**. Звезда не понизилась."
                ),
                color=0xe74c3c,
            )

        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))

    @discord.ui.button(label="Отмена", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        embed = await build_profile_embed(interaction)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))

    async def fail(self, interaction: discord.Interaction, msg: str):
        embed = BotEmbed(title="❌ Ошибка", description=msg, color=0xe74c3c)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))


