async def open_move_view(interaction: discord.Interaction, source: str, author_id: int, page: int = 0):
    user_id = interaction.user.id
    guild_id = interaction.guild_id
    settings = await get_settings(guild_id)
    custom = settings["custom_emojis"]

    async with bot.db.execute("""
        SELECT inv.slot, inv.item_id, i.name, i.emoji, inv.stars
        FROM inventory inv
        JOIN items i ON inv.item_id = i.id
        WHERE inv.user_id = ? AND inv.location = ?
        ORDER BY inv.slot ASC
    """, (user_id, source)) as c:
        rows = await c.fetchall()

    if not rows:
        await interaction.followup.send("❌ В этой локации нет предметов.", ephemeral=True)
        return

    total_pages = max(1, (len(rows) + SHOP_SELECT_PAGE_SIZE - 1) // SHOP_SELECT_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    chunk = rows[page * SHOP_SELECT_PAGE_SIZE: page * SHOP_SELECT_PAGE_SIZE + SHOP_SELECT_PAGE_SIZE]

    options = []
    for slot, item_id, name, default_emoji, stars in chunk:
        emoji_obj = parse_emoji_safe(custom.get(item_id, default_emoji))
        stars_str = f" {stars}★" if stars > 0 else ""
        
        short_name = name[:45] + "..." if len(name) > 45 else name
        options.append(discord.SelectOption(
            label=f"{short_name}{stars_str}",
            value=f"{slot}:{item_id}:{stars}",  # <--- ТРИ ЧАСТИ
            emoji=emoji_obj
        ))

    location_name = {
        "profile": "Энергостанции",
        "storage": "Хранилища",
        "temp": "Временного хранилища",
    }.get(source, "Хранилища")
    embed = BotEmbed(
        title=f"🔀 Перемещение из {location_name}",
        description=f"Страница {page + 1}/{total_pages}\nВыбери предмет для перемещения:",
        color=0x3498db
    )
    
    await interaction.followup.send(
        embed=embed,
        view=MoveView(author_id, source, options, page, total_pages, interaction.message),
        ephemeral=True
    )


class MoveView(SafeView):
    feature_key = "storage"
    def __init__(
        self,
        author_id: int,
        source: str,
        options: list[discord.SelectOption],
        page: int,
        total_pages: int,
        main_message=None,
    ):
        super().__init__(timeout=180)
        self.author_id = author_id
        self.source = source
        self.feature_key = "storage" if source in ("storage", "temp") else None
        self.page = page
        self.total_pages = total_pages
        self.main_message = main_message

        self.add_item(make_select("Выбери предмет", options, self.item_select, row=0))

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            nxt.callback = self.next_page
            self.add_item(nxt)

        close = discord.ui.Button(label="Закрыть", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.danger, row=2)
        close.callback = self.close_window
        self.add_item(close)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    async def item_select(self, interaction: discord.Interaction):
        value = interaction.data["values"][0]
        parts = value.split(":")
        
        slot = int(parts[0])
        item_id = parts[1]
        stars = int(parts[2]) if len(parts) > 2 else 0
        
        await interaction.response.defer()
        await self.do_move(interaction, slot, item_id, stars)

    async def do_move(self, interaction: discord.Interaction, slot: int, item_id: str, stars: int):
        user_id = interaction.user.id
        if self.source == "profile":
            target = "storage"
        elif self.source == "storage":
            target = "profile"
        else:
            target = "storage"
        
        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT item_id, stars, COALESCE(is_locked, 0) FROM inventory "
                    "WHERE user_id = ? AND location = ? AND slot = ?",
                    (user_id, self.source, slot)
                ) as c:
                    row = await c.fetchone()
                if not row:
                    raise ValueError("Предмета уже нет.")
                item_id = row[0]
                stars = row[1]
                is_locked = row[2]

                target_size = await (
                    get_storage_size(user_id)
                    if target == "storage"
                    else get_grid_size(user_id)
                )
                async with bot.db.execute(
                    "SELECT slot FROM inventory "
                    "WHERE user_id = ? AND location = ?",
                    (user_id, target),
                ) as c:
                    used = {r[0] for r in await c.fetchall()}
                free = [s for s in range(target_size) if s not in used]
                if not free:
                    raise ValueError(
                        f"В хранилище нет места (макс. {target_size})."
                        if target == "storage"
                        else f"На энергостанции нет места (макс. {target_size})."
                    )

                new_slot = free[0]
                cur = await bot.db.execute(
                    "DELETE FROM inventory "
                    "WHERE user_id = ? AND location = ? AND slot = ?",
                    (user_id, self.source, slot),
                )
                if cur.rowcount == 0:
                    raise ValueError("Предмета уже нет.")
                await bot.db.execute(
                    "INSERT INTO inventory "
                    "(user_id, slot, item_id, location, stars, is_locked) "
                    "VALUES (?, ?, ?, ?, ?, ?)",
                    (user_id, new_slot, item_id, target, stars, is_locked),
                )
        except (ValueError, aiosqlite.IntegrityError) as exc:
            return await interaction.edit_original_response(
                embed=BotEmbed(
                    title="❌ Ошибка",
                    description=str(exc),
                    color=0xe74c3c,
                ),
                view=None,
            )

        await update_quest_progress(user_id, "move_2")
        await update_quest_progress(user_id, "move_5")
        await sort_inventory(user_id, "profile")
        await sort_inventory(user_id, "storage")
        await sort_inventory(user_id, "temp")

        if target == "storage":
            target_phrase = "в **Хранилище**"
        else:
            target_phrase = "на **Энергостанцию**"
        embed = BotEmbed(
            title="✅ Перемещено",
            description=(
                f"Предмет успешно перемещён {target_phrase}.\n"
                "Закрой это окно и проверь основное меню."
            ),
            color=0x2ecc71
        )
        await interaction.edit_original_response(embed=embed, view=None)

        if self.source == "profile":
            main_embed = await build_profile_embed(interaction)
            main_view = ProfileView(self.author_id)
        elif self.source == "temp":
            main_embed = await build_temp_storage_embed(interaction)
            main_view = TempStorageView(self.author_id)
        else:
            main_embed = await build_storage_embed(interaction)
            main_view = StorageView(self.author_id)

        if self.main_message:
            try:
                await self.main_message.edit(embed=main_embed, view=main_view)
            except discord.HTTPException:
                pass

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        async with bot.db.execute("""
            SELECT inv.slot, inv.item_id, i.name, i.emoji, inv.stars
            FROM inventory inv JOIN items i ON inv.item_id = i.id
            WHERE inv.user_id = ? AND inv.location = ? ORDER BY inv.slot ASC
        """, (self.author_id, self.source)) as c:
            rows = await c.fetchall()
        
        total_pages = max(1, (len(rows) + SHOP_SELECT_PAGE_SIZE - 1) // SHOP_SELECT_PAGE_SIZE)
        page = max(0, min(self.page - 1, total_pages - 1))
        chunk = rows[page * SHOP_SELECT_PAGE_SIZE: page * SHOP_SELECT_PAGE_SIZE + SHOP_SELECT_PAGE_SIZE]
        
        options = []
        for slot, item_id, name, default_emoji, stars in chunk:
            settings = await get_settings(interaction.guild_id)
            emoji_obj = parse_emoji_safe(settings["custom_emojis"].get(item_id, default_emoji))
            stars_str = f" {stars}★" if stars > 0 else ""
            short_name = name[:45] + "..." if len(name) > 45 else name
            options.append(discord.SelectOption(label=f"{short_name}{stars_str}", value=f"{slot}:{item_id}:{stars}", emoji=emoji_obj))
            
        await interaction.edit_original_response(view=MoveView(self.author_id, self.source, options, page, total_pages, self.main_message))

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        async with bot.db.execute("""
            SELECT inv.slot, inv.item_id, i.name, i.emoji, inv.stars
            FROM inventory inv JOIN items i ON inv.item_id = i.id
            WHERE inv.user_id = ? AND inv.location = ? ORDER BY inv.slot ASC
        """, (self.author_id, self.source)) as c:
            rows = await c.fetchall()
        
        total_pages = max(1, (len(rows) + SHOP_SELECT_PAGE_SIZE - 1) // SHOP_SELECT_PAGE_SIZE)
        page = max(0, min(self.page + 1, total_pages - 1))
        chunk = rows[page * SHOP_SELECT_PAGE_SIZE: page * SHOP_SELECT_PAGE_SIZE + SHOP_SELECT_PAGE_SIZE]
        
        options = []
        for slot, item_id, name, default_emoji, stars in chunk:
            settings = await get_settings(interaction.guild_id)
            emoji_obj = parse_emoji_safe(settings["custom_emojis"].get(item_id, default_emoji))
            stars_str = f" {stars}★" if stars > 0 else ""
            short_name = name[:45] + "..." if len(name) > 45 else name
            options.append(discord.SelectOption(label=f"{short_name}{stars_str}", value=f"{slot}:{item_id}:{stars}", emoji=emoji_obj))
            
        await interaction.edit_original_response(view=MoveView(self.author_id, self.source, options, page, total_pages, self.main_message))

    async def close_window(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await interaction.delete_original_response()


