async def get_craft_pity(user_id: int, item_id: str) -> int:
    async with bot.db.execute(
        "SELECT failures FROM craft_pity WHERE user_id = ? AND item_id = ?",
        (user_id, item_id),
    ) as c:
        row = await c.fetchone()
    return (row[0] if row else 0) or 0


async def get_craft_chance(user_id: int, item_id: str, use_cat: bool) -> tuple[float, int, bool]:
    settings = CRAFT_SETTINGS.get(item_id, {"chance": 1.0, "gems": 0})
    base_chance = settings["chance"]
    pet_chance = await get_pet_bonus(user_id, "craft_chance")
    title_chance = await get_title_bonus(user_id, "craft_chance")
    pity = await get_craft_pity(user_id, item_id)
    pity_bonus = min(CRAFT_PITY_MAX, pity * CRAFT_PITY_BONUS)
    final_chance = min(
        1.0,
        base_chance
        + (CATALYST_BONUS if use_cat else 0)
        + pet_chance
        + title_chance
        + pity_bonus,
    )
    guaranteed = pity >= CRAFT_HARD_PITY - 1
    if guaranteed:
        final_chance = 1.0
    return final_chance, pity, guaranteed


async def open_craft_view(interaction: discord.Interaction, author_id: int, page: int = 0):
    user_id = interaction.user.id
    guild_id = interaction.guild_id
    custom = (await get_settings(guild_id))["custom_emojis"]
    chain_items = list(CRAFT_CHAIN.items())

    options_all = []  # <--- ВОТ ЭТА СТРОКА БЫЛА ПОТЕРЯНА
    
    for item_id, next_id in chain_items:
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
            src = await c.fetchone()
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (next_id,)) as c:
            dst = await c.fetchone()
        if not src or not dst:
            continue
        async with bot.db.execute(
            "SELECT COUNT(*) FROM inventory WHERE user_id = ? AND item_id = ? "
            "AND stars = 0 AND location IN ('profile', 'storage')",
            (user_id, item_id)
        ) as c:
            count = (await c.fetchone())[0]
        
        emoji_str = custom.get(item_id, src[1])
        emoji_obj = parse_emoji_safe(emoji_str)  # Используем безопасную функцию
        
        options_all.append(discord.SelectOption(
            label=f"{src[0]} ({count}/{CRAFT_COST}) → {dst[0]}",
            value=item_id,
            emoji=emoji_obj
        ))

    if not options_all:
        await interaction.followup.send("❌ Нет предметов для синтеза.", ephemeral=True)
        return

    total_pages = max(1, (len(options_all) + SHOP_SELECT_PAGE_SIZE - 1) // SHOP_SELECT_PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    chunk = options_all[page * SHOP_SELECT_PAGE_SIZE: page * SHOP_SELECT_PAGE_SIZE + SHOP_SELECT_PAGE_SIZE]

    embed = BotEmbed(
        title="⚗️ Синтез",
        description=(
            f"Страница {page + 1}/{total_pages}\n"
            "Копии берутся из энергостанции и хранилища.\n"
            "Выбери предмет для синтеза:"
        ),
        color=0x3498db
    )
    await interaction.edit_original_response(
        embed=embed,
        view=CraftSelectView(author_id, chunk, page, total_pages)
    )


class CraftSelectView(SafeView):
    feature_key = "craft"
    def __init__(self, author_id: int, options: list[discord.SelectOption], page: int = 0, total_pages: int = 1):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.page = page
        self.total_pages = total_pages
        self.add_item(make_select("Выбери предмет для синтеза", options, self.item_select, row=0))

        if total_pages > 1:
            prev = discord.ui.Button(label="Стр.", emoji=get_emoji("_back"), style=discord.ButtonStyle.secondary, row=1)
            prev.callback = self.prev_page
            self.add_item(prev)
            nxt = discord.ui.Button(label="Стр.", emoji=get_emoji("_forward"), style=discord.ButtonStyle.secondary, row=1)
            nxt.callback = self.next_page
            self.add_item(nxt)

        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.danger, row=2)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    async def item_select(self, interaction: discord.Interaction):
        item_id = interaction.data["values"][0]
        await interaction.response.defer()
        settings = CRAFT_SETTINGS.get(item_id, {"chance": 1.0, "gems": 0})
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
            src = await c.fetchone()
        async with bot.db.execute("SELECT catalysts FROM players WHERE user_id = ?", (interaction.user.id,)) as c:
            cats = (await c.fetchone())[0]

        final_chance, pity, guaranteed = await get_craft_chance(
            interaction.user.id, item_id, False
        )
        chance_str = "100% (гарантия)" if guaranteed else f"{int(final_chance * 100)}%"
        pity_str = (
            f"\nPity: **{pity}/{CRAFT_HARD_PITY - 1}** "
            f"(+{int(min(CRAFT_PITY_MAX, pity * CRAFT_PITY_BONUS) * 100)}%)"
            if pity
            else ""
        )

        embed = BotEmbed(
            title="⚗️ Синтез",
            description=(
                f"Предмет: {src[1]} **{src[0]}**\n"
                f"Шанс успеха: **{chance_str}**{pity_str}\n"
                f"Стоимость: 💎 {settings['gems']}\n\n"
                f"Использовать катализатор (+{int(CATALYST_BONUS * 100)}%)?\n"
                f"У тебя катализаторов: **{cats}**"
            ),
            color=0x3498db
        )
        await interaction.edit_original_response(embed=embed, view=CraftConfirmView(self.author_id, item_id))

    async def prev_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_craft_view(interaction, self.author_id, self.page - 1)

    async def next_page(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await open_craft_view(interaction, self.author_id, self.page + 1)

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        await go_back(interaction, self.author_id, fallback="profile")


class CraftConfirmView(SafeView):
    feature_key = "craft"
    def __init__(self, author_id: int, item_id: str):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.item_id = item_id

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Без катализатора", emoji=get_emoji("_synthesis"), style=discord.ButtonStyle.primary)
    async def no_catalyst(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        await self.do_craft(interaction, False)

    @discord.ui.button(label="С катализатором", emoji=get_emoji("_catalyst"), style=discord.ButtonStyle.success)
    async def with_catalyst(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        await self.do_craft(interaction, True)

    @discord.ui.button(label="Отмена", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.defer()
        embed = await build_profile_embed(interaction)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))

    async def do_craft(self, interaction: discord.Interaction, use_cat: bool):
        user_id = interaction.user.id
        item_id = self.item_id
        next_id = CRAFT_CHAIN[item_id]
        settings = CRAFT_SETTINGS.get(item_id, {"chance": 1.0, "gems": 0})
        base_chance, gem_cost = settings["chance"], settings["gems"]

        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (item_id,)) as c:
            src = await c.fetchone()
        async with bot.db.execute("SELECT name, emoji FROM items WHERE id = ?", (next_id,)) as c:
            dst = await c.fetchone()
        if not src or not dst:
            return await self.fail(interaction, "❌ Генератор не найден в базе.")
        src_name, src_emoji = src
        dst_name, dst_emoji = dst

        try:
            async with db_transaction():
                async with bot.db.execute(
                    "SELECT location, slot FROM inventory "
                    "WHERE user_id = ? AND item_id = ? AND stars = 0 "
                    "AND location IN ('profile', 'storage') "
                    "ORDER BY CASE location WHEN 'profile' THEN 0 ELSE 1 END, "
                    "slot LIMIT ?",
                    (user_id, item_id, CRAFT_COST),
                ) as c:
                    owned = await c.fetchall()

                if len(owned) < CRAFT_COST:
                    raise ValueError(
                        f"Нужно {CRAFT_COST} × {src_name} без звёзд, у тебя {len(owned)}."
                    )

                async with bot.db.execute(
                    "SELECT gems, catalysts FROM players WHERE user_id = ?", (user_id,)
                ) as c:
                    gems, cats = await c.fetchone()
                if gems < gem_cost:
                    raise ValueError(f"Нужно 💎 {gem_cost}, у тебя {gems}.")
                if use_cat and cats < 1:
                    raise ValueError("Нет катализаторов.")

                for location, slot in owned:
                    await bot.db.execute(
                        "DELETE FROM inventory WHERE user_id = ? AND location = ? AND slot = ?",
                        (user_id, location, slot),
                    )

                if gem_cost > 0:
                    cur = await bot.db.execute(
                        "UPDATE players SET gems = gems - ? "
                        "WHERE user_id = ? AND gems >= ?",
                        (gem_cost, user_id, gem_cost),
                    )
                    if cur.rowcount == 0:
                        raise ValueError("Не хватает гемов.")

                catalyst_used = 0
                if use_cat:
                    cur = await bot.db.execute(
                        "UPDATE players SET catalysts = catalysts - 1 "
                        "WHERE user_id = ? AND catalysts >= 1",
                        (user_id,),
                    )
                    if cur.rowcount == 0:
                        raise ValueError("Нет катализаторов.")
                    catalyst_used = 1

                final_chance, pity, guaranteed = await get_craft_chance(
                    user_id, item_id, use_cat
                )
                success = guaranteed or random.random() < final_chance

                await bot.db.execute(
                    "INSERT INTO craft_log "
                    "(user_id, item_id, success, gems_spent, catalyst_used) "
                    "VALUES (?, ?, ?, ?, ?)",
                    (user_id, item_id, int(success), gem_cost, catalyst_used),
                )

                if success:
                    try:
                        await place_items(
                            user_id, next_id, 1, commit=False,
                            stars=CRAFT_RESULT_STARS
                        )
                    except ValueError:
                        # Мы только что освободили слоты — кладём результат
                        # в первый освободившийся слот, чтобы не потерять его.
                        loc, slot = owned[0]
                        await bot.db.execute(
                            "INSERT INTO inventory "
                            "(user_id, slot, item_id, location, stars) "
                            "VALUES (?, ?, ?, ?, ?)",
                            (user_id, slot, next_id, loc, CRAFT_RESULT_STARS),
                        )
                else:
                    # При провале возвращаем одну исходную копию, чтобы
                    # синтез не был слишком суровым.
                    try:
                        await place_items(
                            user_id, item_id, 1, commit=False, stars=0
                        )
                    except ValueError:
                        log.exception(
                            "Не удалось вернуть копию после провала синтеза %s",
                            user_id,
                        )

                await bot.db.execute(
                    "UPDATE players SET total_crafts = total_crafts + 1, "
                    "total_successes = total_successes + ? WHERE user_id = ?",
                    (int(success), user_id),
                )
                if success:
                    await bot.db.execute(
                        "DELETE FROM craft_pity WHERE user_id = ? AND item_id = ?",
                        (user_id, item_id),
                    )
                else:
                    await bot.db.execute("""
                        INSERT INTO craft_pity (user_id, item_id, failures)
                        VALUES (?, ?, 1)
                        ON CONFLICT(user_id, item_id)
                        DO UPDATE SET failures = failures + 1
                    """, (user_id, item_id))
        except ValueError as e:
            return await self.fail(interaction, f"❌ {e}")

        await sort_inventory(user_id, "profile")
        await sort_inventory(user_id, "storage")

        await update_story_quests(user_id, "synthesize", 1)
        await update_quest_progress(user_id, "craft_1")
        await update_quest_progress(user_id, "craft_3")
        await update_quest_progress(user_id, "craft_5")
        if success:
            await update_quest_progress(user_id, "success_2")
        if use_cat:
            await update_quest_progress(user_id, "use_catalyst")

        clan = await get_clan(user_id)
        if clan:
            await update_clan_quest(clan[0], "synthesize", 1)

        unlocked = await check_achievements(user_id)
        await add_season_xp(
            user_id,
            season_xp_amount(
                "craft_success" if success else "craft_fail"
            ),
            interaction.guild_id,
            action="craft_success" if success else "craft_fail",
        )
        onboarding = await complete_onboarding_step(user_id, "craft")

        if guaranteed:
            chance_str = "🎲 100% (гарантия pity)"
        else:
            chance_str = f"🎲 {int(final_chance * 100)}%"
            if pity:
                chance_str += f" (pity {pity}/{CRAFT_HARD_PITY - 1})"
            if use_cat:
                chance_str += f" (база {int(base_chance * 100)}% + 🧪)"
        gem_str = f" | 💎 {gem_cost}" if gem_cost else ""
        if success:
            msg = (
                f"⚗️ Успех! {CRAFT_COST}×{src_emoji} {src_name} → "
                f"1×{dst_emoji} {dst_name} "
                f"{CRAFT_RESULT_STARS}★\n{chance_str}{gem_str}"
            )
        else:
            msg = (
                f"💥 Провал! Сгорело {CRAFT_COST - 1}×{src_emoji} "
                f"{src_name}, 1 копия возвращена.\n{chance_str}{gem_str}"
            )
        if unlocked:
            msg += "\n🏆 " + ", ".join(f"{e} {n}" for e, n, _ in unlocked)
        if onboarding:
            msg += (
                f"\n🚀 Первый шаг: **{ONBOARDING_STEPS['craft'][0]}** "
                f"+🪙 {onboarding['coins']} +💎 {onboarding['gems']}."
            )

        embed = BotEmbed(title="⚗️ Результат синтеза", description=msg, color=0x9b59b6)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))

    async def fail(self, interaction: discord.Interaction, msg: str):
        embed = BotEmbed(title="❌ Ошибка", description=msg, color=0xe74c3c)
        await interaction.edit_original_response(embed=embed, view=ProfileView(self.author_id))


