class CatalystSelectView(SafeView):
    feature_key = "shop"
    def __init__(self, author_id: int, return_to: str = "shop"):
        super().__init__(timeout=120)
        self.author_id = author_id
        self.return_to = "profile" if return_to == "profile" else "shop"
        options = [
            discord.SelectOption(
                label=f"{q} шт — {CATALYST_PRICE * q} гемов",
                value=str(q),
                emoji=parse_emoji_safe(get_emoji("_catalyst")),
            )
            for q in (1, 2, 5, 10, 25)
        ]
        self.add_item(make_select("Сколько катализаторов купить?", options, self.quantity_select, row=0))
        back = discord.ui.Button(label="Отмена", emoji=get_emoji("_cancel"), style=discord.ButtonStyle.secondary, row=1)
        back.callback = self.cancel
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.author_id:
            await interaction.response.send_message("❌ Не твоё меню.", ephemeral=True)
            return False
        return True

    async def quantity_select(self, interaction: discord.Interaction):
        await interaction.response.defer()
        qty = int(interaction.data["values"][0])
        user_id = interaction.user.id
        cost = CATALYST_PRICE * qty

        try:
            async with db_transaction():
                cursor = await bot.db.execute(
                    "UPDATE players SET gems = gems - ?, catalysts = catalysts + ? "
                    "WHERE user_id = ? AND gems >= ?",
                    (cost, qty, user_id, cost),
                )
                if cursor.rowcount == 0:
                    raise ValueError(f"Нужно 💎 {cost}.")
        except ValueError as e:
            return await self.fail(interaction, f"❌ {e}")

        async with bot.db.execute(
            "SELECT catalysts FROM players WHERE user_id = ?", (user_id,)
        ) as c:
            total = (await c.fetchone())[0] or 0

        embed = BotEmbed(
            title="🧪 Катализаторы",
            description=(
                f"✅ Куплено **{qty}** шт. за 💎 {cost}.\n"
                f"Всего катализаторов: **🧪 {total}**."
            ),
            color=0x2ecc71,
        )
        await interaction.followup.send(embed=embed, ephemeral=True)
        if self.return_to == "profile":
            await interaction.edit_original_response(
                embed=await build_profile_embed(interaction),
                view=ProfileView(self.author_id),
            )
        else:
            await interaction.edit_original_response(
                embed=BotEmbed(
                    title="🛒 Магазин",
                    description="Выбери раздел:",
                    color=0xf1c40f,
                ),
                view=ShopHubView(self.author_id),
            )

    async def fail(self, interaction: discord.Interaction, msg: str):
        embed = BotEmbed(title="❌ Ошибка", description=msg, color=0xe74c3c)
        await interaction.edit_original_response(
            embed=embed,
            view=CatalystSelectView(self.author_id, return_to=self.return_to),
        )

    async def cancel(self, interaction: discord.Interaction):
        await interaction.response.defer()
        if self.return_to == "profile":
            await interaction.edit_original_response(
                embed=await build_profile_embed(interaction),
                view=ProfileView(self.author_id),
            )
        else:
            await interaction.edit_original_response(
                embed=BotEmbed(
                    title="🛒 Магазин",
                    description="Выбери раздел:",
                    color=0xf1c40f,
                ),
                view=ShopHubView(self.author_id),
            )


