class SettingsCommandsView(AdminView):
    def __init__(self, author_id: int, disabled: list | None = None, timeout: int = 120):
        super().__init__(timeout=timeout)
        self.author_id = author_id
        disabled_set = set(disabled or [])
        options = [
            discord.SelectOption(
                label=name,
                value=key,
                default=key in disabled_set,
                emoji=parse_emoji_safe(get_emoji("_settings")),
            )
            for key, name in TOGGLEABLE_COMMANDS.items()
        ]
        self.add_item(make_select(
            "Выбери функции для отключения",
            options,
            self.toggle,
            row=0,
            min_values=0,
            max_values=len(options),
        ))
        back = discord.ui.Button(label="Назад", emoji=get_emoji("_back"), style=discord.ButtonStyle.danger, row=1)
        back.callback = self.back
        self.add_item(back)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await super().interaction_check(interaction)

    async def toggle(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        guild_id = interaction.guild_id
        values = list(interaction.data.get("values", []))
        await save_setting(guild_id, "disabled_commands", values, actor_id=interaction.user.id)
        names = [TOGGLEABLE_COMMANDS[c] for c in values]
        await interaction.followup.send(f"✅ Отключено: {', '.join(names) if names else 'ничего'}.", ephemeral=True)

    async def back(self, interaction: discord.Interaction):
        await interaction.response.defer()
        embed = BotEmbed(title="🔧 Настройки сервера", color=0x808080)
        await interaction.edit_original_response(embed=embed, view=SettingsView(self.author_id))


class SettingsStatusRoleModal(discord.ui.Modal, title="Роль за статус"):
    status = discord.ui.TextInput(label="Статус (vip/platinum/gold/diamond)", required=True)
    role_id = discord.ui.TextInput(label="ID роли", required=True)

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        status = self.status.value.strip().lower()
        if status not in ("vip", "platinum", "gold", "diamond"):
            await interaction.followup.send("❌ vip/platinum/gold/diamond.", ephemeral=True)
            return
        try:
            role_id = int(self.role_id.value)
        except ValueError:
            await interaction.followup.send("❌ ID роли — число.", ephemeral=True)
            return
        guild_id = interaction.guild_id
        settings = await get_settings(guild_id)
        roles = settings["status_roles"]
        roles[status] = role_id
        await save_setting(guild_id, "status_roles", roles, actor_id=interaction.user.id)
        await interaction.followup.send(f"✅ Роль <@&{role_id}> за статус **{status}**.", ephemeral=True)


