class SettingsAdminRoleModal(discord.ui.Modal, title="Роль администратора"):
    role_id = discord.ui.TextInput(label="ID роли (0 — сбросить)", required=True)

    def __init__(self, author_id: int):
        super().__init__()
        self.author_id = author_id

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        guild_id = interaction.guild_id
        try:
            role_id = int(self.role_id.value)
            if role_id < 0:
                raise ValueError
        except ValueError:
            await interaction.followup.send("❌ ID роли >= 0.", ephemeral=True)
            return
        if role_id == 0:
            await save_setting(guild_id, "admin_role_id", None, actor_id=interaction.user.id)
            await interaction.followup.send("✅ Роль админа сброшена.", ephemeral=True)
            return
        guild = interaction.guild
        role = guild.get_role(role_id) if guild else None
        if not role:
            await interaction.followup.send(f"❌ Роль `{role_id}` не найдена.", ephemeral=True)
            return
        await save_setting(guild_id, "admin_role_id", role_id, actor_id=interaction.user.id)
        await interaction.followup.send(f"✅ Роль <@&{role_id}> получила доступ.", ephemeral=True)


class EditEmojiModal(discord.ui.Modal, title="Изменить эмодзи"):
    emoji = discord.ui.TextInput(
        label="Новый эмодзи",
        placeholder="👑 или <:name:id>; пусто — сбросить",
        required=False,
        max_length=100,
    )

    def __init__(self, author_id: int, key: str):
        super().__init__()
        self.author_id = author_id
        self.key = key
        label = EMOJI_KEYS.get(key, (key, "?"))[0]
        self.title = f"Эмодзи: {label}"[:45]

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        if interaction.guild_id is None:
            return await interaction.followup.send(
                "❌ Настройки доступны только на сервере.",
                ephemeral=True,
            )

        value = self.emoji.value.strip()
        settings = await get_settings(interaction.guild_id)
        custom = settings["custom_emojis"]
        label = EMOJI_KEYS.get(self.key, (self.key, "?"))[0]

        if value:
            if not is_valid_emoji(value):
                return await interaction.followup.send(
                    "❌ Эмодзи должен быть юникод-символом (👑) "
                    "или кастомным (`<:name:id>`).",
                    ephemeral=True,
                )
            custom[self.key] = value
            message = f"✅ Эмодзи для «{label}» обновлён."
        else:
            custom.pop(self.key, None)
            message = f"✅ Эмодзи для «{label}» сброшен."

        await save_setting(interaction.guild_id, "custom_emojis", custom, actor_id=interaction.user.id)
        await interaction.followup.send(message, ephemeral=True)


