@bot.tree.command(name="уведомления", description="Показать уведомления и пропущенные события")
async def notifications_cmd(interaction: discord.Interaction):
    user_id = interaction.user.id
    async with bot.db.execute(
        "SELECT title, body, created_at FROM notification_fallback "
        "WHERE user_id = ? ORDER BY id DESC LIMIT 10",
        (user_id,),
    ) as c:
        rows = await c.fetchall()
    embed = await build_notification_center_embed(user_id)
    if rows:
        text = "\n".join(
            f"**{title}** — {body}\n`{str(created_at)[:16]}`"
            for title, body, created_at in rows
        )
        embed.add_field(
            name=f"{get_emoji('_notifications')} Пропущенные в ЛС",
            value=text[:1024],
            inline=False,
        )
        await bot.db.execute(
            "DELETE FROM notification_fallback WHERE user_id = ?", (user_id,)
        )
        await commit_if_needed()
    await interaction.response.send_message(embed=embed, ephemeral=True)


@bot.tree.command(name="меню", description="Открыть главное меню энергостанции")
async def main_menu(interaction: discord.Interaction):
    guild_id = interaction.guild_id
    user_id = interaction.user.id
    
    # Проверяем игрока
    async with bot.db.execute("SELECT 1 FROM players WHERE user_id = ?", (user_id,)) as c:
        player_exists = await c.fetchone()
        
    if not player_exists:
        embed = await build_welcome_embed(interaction)
        await interaction.response.send_message(
            embed=embed, view=WelcomeView(user_id), ephemeral=True
        )
        return

    # Стандартная логика
    reset_nav(user_id)
    notification = await get_menu_welcome_notification(user_id, guild_id)
    await collect_income(user_id, guild_id)
    embed = await build_main_embed(interaction)
    view = MainMenuView(user_id)
    
    # Используем только ОДИН метод ответа, в зависимости от ситуации
    if notification:
        await interaction.response.send_message(notification, ephemeral=True)
        await interaction.followup.send(embed=embed, view=view, ephemeral=True)
    else:
        await interaction.response.send_message(embed=embed, view=view, ephemeral=True)


@bot.tree.command(name="админ_панель", description="Панель администратора")
async def admin_panel(interaction: discord.Interaction):
    # В ЛС interaction.user — User без guild_permissions. Панель только для сервера.
    if interaction.guild is None:
        return await interaction.response.send_message(
            "❌ Команда доступна только на сервере.",
            ephemeral=True,
        )

    if not await has_admin_access(interaction):
        return await interaction.response.send_message(
            "❌ У тебя нет доступа к админ-панели.\n\n"
            "Доступ есть у:\n"
            "• владельца бота;\n"
            "• владельца сервера;\n"
            "• участника с правом Administrator;\n"
            "• роли из настройки `admin_role_id`.\n\n"
            "Владелец сервера может настроить роль в админ-панели.",
            ephemeral=True,
        )

    embed = BotEmbed(
        title="🛡️ Панель администратора",
        description="Локальные действия сервера. Глобальные настройки — в разделе «Владелец».",
        color=0xe74c3c
    )
    view = AdminPanelView(interaction.user.id)
    await interaction.response.send_message(embed=embed, view=view, ephemeral=True)


@bot.tree.command(name="health", description="Состояние бота и метрики")
async def health_cmd(interaction: discord.Interaction):
    if not await is_global_owner(interaction):
        return await interaction.response.send_message(
            "❌ Команда доступна только владельцу бота.",
            ephemeral=True,
        )

    await interaction.response.defer(ephemeral=True)
    snapshot = await bot.build_health_snapshot(deep=True)
    latency = snapshot.get("gateway_latency_ms")
    quick_check = snapshot.get("db_quick_check", "—")
    embed = BotEmbed(
        title="🩺 Gen Mania — health",
        description=(
            f"Uptime: **{snapshot['uptime_seconds']} c**\n"
            f"Gateway: **{latency if latency is not None else '—'} ms**\n"
            f"Серверов: **{snapshot['guilds']}**\n"
            f"БД: **{snapshot['db_size_bytes']} байт**, "
            f"quick_check: **{quick_check}**"
        ),
        color=0x2ecc71,
    )
    embed.add_field(
        name="Команды",
        value=(
            f"Всего: **{snapshot['commands_total']}**\n"
            f"Ошибок: **{snapshot['command_errors']}**\n"
            f"Avg: **{snapshot['command_avg_ms']} ms** · "
            f"p95: **{snapshot['command_p95_ms']} ms**"
        ),
        inline=True,
    )
    embed.add_field(
        name="DB-транзакции",
        value=(
            f"Всего: **{snapshot['db_tx_total']}**\n"
            f"Ошибок: **{snapshot['db_tx_errors']}**\n"
            f"Avg: **{snapshot['db_tx_avg_ms']} ms** · "
            f"p95: **{snapshot['db_tx_p95_ms']} ms**\n"
            f"Slow: **{snapshot['slow_db_tx']}**"
        ),
        inline=True,
    )
    tasks = snapshot.get("tasks", [])
    dead = [task["name"] for task in tasks if task["done"]]
    tasks_value = (
        f"Живы: **{snapshot.get('tasks_alive', 0)}/{len(tasks)}**"
    )
    if dead:
        tasks_value += "\nЗавершились: " + ", ".join(dead[:5])
    embed.add_field(name="Фоновые задачи", value=tasks_value, inline=False)
    await interaction.followup.send(embed=embed, ephemeral=True)


# ============================================================
#  🌐 СОБЫТИЯ СЕРВЕРОВ
# ============================================================

@bot.event
async def on_ready():
    """Один раз за процесс считывает роли/права всех серверов."""
    if bot._guild_access_synced:
        return
    bot._guild_access_synced = True
    await sync_all_guild_access()


@bot.event
async def on_guild_join(guild):
    _tax_rate_cache.clear()
    await sync_guild_access(guild, reason="join")


@bot.event
async def on_guild_remove(guild):
    _tax_rate_cache.clear()


@bot.event
async def on_member_join(member):
    _tax_rate_cache.pop(member.id, None)


@bot.event
async def on_member_remove(member):
    _tax_rate_cache.pop(member.id, None)


@bot.event
async def on_guild_role_update(before, after):
    await sync_guild_access(after.guild, reason="role_update")


@bot.event
async def on_guild_role_delete(role):
    await sync_guild_access(role.guild, reason="role_delete")


# ============================================================
#  🚀 ЗАПУСК
# ============================================================

if __name__ == "__main__":
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
    )
    token = os.getenv("DISCORD_BOT_TOKEN")
    if not token:
        raise SystemExit(
            "DISCORD_BOT_TOKEN не задан. Добавь переменную окружения "
            "или настрой .env на хостинге."
        )

    def _handle_sigterm(*_args):
        try:
            asyncio.get_event_loop().create_task(bot.close())
        except Exception:
            log.exception("Не удалось запустить graceful shutdown по SIGTERM")

    try:
        signal.signal(signal.SIGTERM, _handle_sigterm)
    except (ValueError, OSError):
        pass

    bot.run(token)
